import React,{useEffect,useMemo,useState} from 'react';

const useOnline=()=>{const [online,setOnline]=useState(navigator.onLine);useEffect(()=>{const on=()=>setOnline(true),off=()=>setOnline(false);window.addEventListener('online',on);window.addEventListener('offline',off);return()=>{window.removeEventListener('online',on);window.removeEventListener('offline',off)}},[]);return online};
import {createRoot} from 'react-dom/client';
import {Activity,ArrowDownLeft,ArrowUpRight,BarChart3,FileText,TrendingUp,CalendarClock,CalendarDays,Bell,Check,ChevronRight,CircleDollarSign,CreditCard,Download,FileUp,Home as HomeIcon,KeyRound,Landmark,Leaf,LogOut,Monitor,Plus,Repeat2,Search,Settings,Shield,Smartphone,Sparkles,Target,Trash2,UserRound,Wallet,X,HandCoins,MessageCircle} from 'lucide-react';
import {api,User,Account,Category,Transaction,Recurrence,Payment,Card,Goal,Dashboard,RecurrenceSummary,Investment,InvestmentSummary} from './api';
import './styles.css';

if ('serviceWorker' in navigator) window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));

type Mascot={id:string;name:string;animal:string;emoji:string;personality:string;intro:string};
const MASCOTS:Mascot[]=[
 {id:'bento',name:'Bento',animal:'Ursinho',emoji:'🐻',personality:'Tranquilo e acolhedor',intro:'Vamos cuidar das suas finanças com calma.'},
 {id:'nico',name:'Nico',animal:'Raposa',emoji:'🦊',personality:'Curioso e observador',intro:'Vamos descobrir os padrões do seu dinheiro.'},
 {id:'luna',name:'Luna',animal:'Gatinha',emoji:'🐱',personality:'Organizada e cuidadosa',intro:'Um passo de cada vez, tudo no lugar.'},
 {id:'tito',name:'Tito',animal:'Tartaruga',emoji:'🐢',personality:'Paciente e constante',intro:'Constância vale mais que pressa.'},
 {id:'pip',name:'Pip',animal:'Coelhinho',emoji:'🐰',personality:'Leve e otimista',intro:'Vamos deixar a vida financeira mais leve.'}
];
const mascotById=(id?:string)=>MASCOTS.find(m=>m.id===id)||MASCOTS[0];
const brl=(v:number)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(v||0));
const dateBR=(v:string)=>new Date(`${v.slice(0,10)}T12:00:00`).toLocaleDateString('pt-BR');
const periodLabel=(p:string)=>({semanal:'Semanal',quinzenal:'Quinzenal',mensal:'Mensal',bimestral:'Bimestral',trimestral:'Trimestral',semestral:'Semestral',anual:'Anual',personalizada:'Personalizada'} as any)[p]||p;

type Page='inicio'|'lancamentos'|'contas'|'recorrencias'|'cartoes'|'investimentos'|'metas'|'agenda'|'relatorios'|'inteligencia'|'dividas'|'documentos'|'assistente'|'config';

function Auth({onAuth}:{onAuth:(u:User)=>void}){
 const [mode,setMode]=useState<'login'|'register'>('login');const [nome,setNome]=useState('');const [email,setEmail]=useState('');const [password,setPassword]=useState('');const [privacy,setPrivacy]=useState(false);const [mfaCode,setMfaCode]=useState('');const [challenge,setChallenge]=useState('');const [mfaUser,setMfaUser]=useState<User|null>(null);const [error,setError]=useState('');const [loading,setLoading]=useState(false);
 async function submit(e:React.FormEvent){e.preventDefault();setError('');setLoading(true);try{const r:any=mode==='login'?await api.login({email,password}):await api.register({nome,email,password,aceite_privacidade:privacy,versao_privacidade:'1.0'});if(r.mfa_required){setChallenge(r.challenge_token);setMfaUser(r.user);return}onAuth(r.user)}catch(e){setError(e instanceof Error?e.message:'Não foi possível entrar')}finally{setLoading(false)}}
 async function verify(e:React.FormEvent){e.preventDefault();setError('');setLoading(true);try{const r=await api.verifyMfaLogin({challenge_token:challenge,code:mfaCode});onAuth(r.user)}catch(e){setError(e instanceof Error?e.message:'Código inválido')}finally{setLoading(false)}}
 if(challenge)return <div className="auth-screen"><div className="auth-art"><div className="brand"><Leaf size={18}/><strong>Meu Controle</strong></div><div className="auth-copy"><span className="eyebrow">SEGUNDA CAMADA</span><h1>Mais uma etapa.<br/>Mais proteção.</h1><p>Abra seu aplicativo autenticador e informe o código de 6 dígitos.</p></div><div className="auth-mascot">🛡️<span>Proteção em duas etapas.</span></div></div><div className="auth-card"><div className="mobile-brand"><Leaf size={18}/><strong>Meu Controle</strong></div><span className="eyebrow">AUTENTICAÇÃO EM DOIS FATORES</span><h2>Confirme sua entrada</h2><p className="muted">{mfaUser?.email}</p><form onSubmit={verify}><label>Código de 6 dígitos<input autoFocus inputMode="numeric" maxLength={6} value={mfaCode} onChange={e=>setMfaCode(e.target.value.replace(/\D/g,''))} required placeholder="000000"/></label>{error&&<div className="form-error">{error}</div>}<button className="primary-btn wide" disabled={loading}>{loading?'Verificando...':'Confirmar acesso'}<Check size={16}/></button></form><button className="switch-btn" onClick={()=>{setChallenge('');setMfaCode('');setError('')}}>Voltar</button></div></div>;
 return <div className="auth-screen"><div className="auth-art"><div className="brand"><Leaf size={18}/><strong>Meu Controle</strong></div><div className="auth-copy"><span className="eyebrow">SUA VIDA FINANCEIRA</span><h1>Mais clareza.<br/>Menos complicação.</h1><p>Um cantinho tranquilo para organizar seu dinheiro, acompanhar objetivos e tomar decisões com mais segurança.</p></div><div className="auth-mascot">🐻<span>Seu dinheiro, sem complicação.</span></div></div><div className="auth-card"><div className="mobile-brand"><Leaf size={18}/><strong>Meu Controle</strong></div><span className="eyebrow">{mode==='login'?'BEM-VINDO DE VOLTA':'COMEÇAR'}</span><h2>{mode==='login'?'Entrar na sua conta':'Criar minha conta'}</h2><p className="muted">{mode==='login'?'Continue de onde parou.':'Leva só um minutinho.'}</p><form onSubmit={submit}>{mode==='register'&&<label>Nome<input value={nome} onChange={e=>setNome(e.target.value)} required placeholder="Como podemos chamar você?"/></label>}<label>E-mail<input type="email" value={email} onChange={e=>setEmail(e.target.value)} required placeholder="voce@email.com"/></label><label>Senha<input type="password" value={password} onChange={e=>setPassword(e.target.value)} required minLength={12} placeholder="Mínimo de 12 caracteres"/></label>{mode==='register'&&<label className="check-line"><input type="checkbox" checked={privacy} onChange={e=>setPrivacy(e.target.checked)}/> Li o resumo da Política de Privacidade e concordo com o tratamento dos dados necessários ao funcionamento do serviço.</label>}{error&&<div className="form-error">{error}</div>}<button className="primary-btn wide" disabled={loading}>{loading?'Entrando...':mode==='login'?'Entrar':'Criar conta'}<ChevronRight size={16}/></button></form><button className="switch-btn" onClick={()=>{setMode(mode==='login'?'register':'login');setError('')}}>{mode==='login'?'Ainda não tenho uma conta':'Já tenho uma conta'}</button>{mode==='login'&&<button className="switch-btn" onClick={()=>{const e=window.prompt('Digite seu e-mail para receber a recuperação:');if(e)api.recoverPassword(e).then(r=>alert(r.dev_token?`Ambiente de desenvolvimento — token: ${r.dev_token}`:'Confira seu e-mail.')).catch(err=>alert(err.message))}}>Esqueci minha senha</button>}</div></div>}

function MascotPicker({initial,onSelect}:{initial?:string;onSelect:(m:Mascot)=>void}){const [selected,setSelected]=useState(initial||'bento');return <div className="mascot-screen"><div className="mascot-header"><Leaf size={20}/><strong>Meu Controle</strong></div><span className="eyebrow">UMA COMPANHIA PARA A JORNADA</span><h1>Escolha quem vai acompanhar você.</h1><p>Você pode trocar seu mascote depois nas configurações.</p><div className="mascot-grid">{MASCOTS.map(m=><button key={m.id} className={`mascot-card ${selected===m.id?'selected':''}`} onClick={()=>setSelected(m.id)}><div className="mascot-emoji">{m.emoji}</div><strong>{m.name}</strong><span>{m.personality}</span></button>)}</div><button className="primary-btn mascot-continue" onClick={()=>onSelect(mascotById(selected))}>Continuar com {mascotById(selected).name}<ChevronRight size={16}/></button></div>}

function Shell({page,setPage,user,mascot,onLogout,children}:{page:Page;setPage:(p:Page)=>void;user:User;mascot:Mascot;onLogout:()=>void;children:React.ReactNode}){const nav:[Page,string,React.ReactNode][]=[['inicio','Início',<HomeIcon size={17}/>],['lancamentos','Lançamentos',<Activity size={17}/>],['contas','Contas',<Wallet size={17}/>],['recorrencias','Recorrências',<Repeat2 size={17}/>],['cartoes','Cartões',<CreditCard size={17}/>],['investimentos','Investimentos',<TrendingUp size={17}/>],['metas','Metas',<Target size={17}/>],['agenda','Agenda',<CalendarDays size={17}/>],['relatorios','Relatórios',<FileText size={17}/>],['inteligencia','Minha Vida',<Sparkles size={17}/>],['dividas','Dívidas',<HandCoins size={17}/>],['documentos','Documentos',<FileUp size={17}/>],['assistente','Assistente',<MessageCircle size={17}/>],['config','Configurações',<Settings size={17}/>]];return <div className="app-shell"><OfflineBanner/><InstallPrompt/><aside className="sidebar"><div className="brand app-brand"><Leaf size={18}/><span>Meu Controle</span></div><nav>{nav.map(([id,label,icon])=><button key={id} className={page===id?'active':''} onClick={()=>setPage(id)}>{icon}<span>{label}</span></button>)}</nav><div className="sidebar-bottom"><div className="user-chip"><div className="avatar">{mascot.emoji}</div><div><strong>{user.nome||'Você'}</strong><small>{user.email}</small></div></div><button className="logout-btn" onClick={onLogout}><LogOut size={16}/> Sair</button></div></aside><main className="main-area"><header className="topbar"><div className="mobile-title"><Leaf size={17}/><strong>Meu Controle</strong></div><div className="top-actions"><button className="icon-btn" onClick={()=>setPage('lancamentos')} aria-label="Buscar lançamentos"><Search size={18}/></button><button className="icon-btn" onClick={()=>setPage('agenda')} aria-label="Abrir agenda"><CalendarClock size={18}/></button><button className="mascot-mini" onClick={()=>setPage('config')}>{mascot.emoji}<span>{mascot.name}</span></button></div></header>{children}</main><button className="quick-add" onClick={()=>setPage('lancamentos')} aria-label="Novo lançamento"><Plus size={22}/><span>Novo lançamento</span></button><nav className="mobile-nav"><button className={page==='inicio'?'active':''} onClick={()=>setPage('inicio')}><HomeIcon size={18}/><span>Início</span></button><button className={page==='lancamentos'?'active':''} onClick={()=>setPage('lancamentos')}><Activity size={18}/><span>Lançamentos</span></button><button className="mobile-nav-plus" onClick={()=>setPage('lancamentos')} aria-label="Novo lançamento"><Plus size={21}/></button><button className={page==='agenda'?'active':''} onClick={()=>setPage('agenda')}><CalendarDays size={18}/><span>Agenda</span></button><button className={page==='config'?'active':''} onClick={()=>setPage('config')}><Settings size={18}/><span>Mais</span></button></nav><MascotBubble mascot={mascot} page={page}/></div>}


function OfflineBanner(){const online=useOnline();return !online?<div className="offline-banner">Você está offline. O app continua disponível para consulta, mas novas movimentações serão feitas somente quando a conexão voltar.</div>:null}
function InstallPrompt(){const [event,setEvent]=useState<any>(null);const [dismissed,setDismissed]=useState(()=>sessionStorage.getItem('mcf_install_dismissed')==='1');useEffect(()=>{const h=(e:any)=>{e.preventDefault();setEvent(e)};window.addEventListener('beforeinstallprompt',h);return()=>window.removeEventListener('beforeinstallprompt',h)},[]);if(!event||dismissed)return null;return <div className="install-prompt"><div><strong>Levar o Meu Controle para o celular?</strong><small>Instale como aplicativo para abrir mais rápido e usar em tela cheia.</small></div><button className="soft-btn" onClick={async()=>{await event.prompt();setEvent(null)}}>Instalar</button><button className="close-pop" onClick={()=>{sessionStorage.setItem('mcf_install_dismissed','1');setDismissed(true)}}><X size={15}/></button></div>}

function MascotBubble({mascot,page}:{mascot:Mascot;page:Page}){const [open,setOpen]=useState(false);const text=page==='inicio'?mascot.intro:page==='lancamentos'?'Anotado com calma. O histórico ajuda a enxergar o todo.':page==='recorrencias'?'Eu só registro que um compromisso foi pago quando você confirmar. O aplicativo não realiza pagamentos.':page==='cartoes'?'Compras parceladas ficam como compromisso futuro para controle. O aplicativo não realiza pagamentos.':page==='investimentos'?'Aqui você acompanha o patrimônio investido sem confundir rendimento com dinheiro disponível.':page==='metas'?'Pequenos aportes também contam.':page==='agenda'?'Aqui você enxerga os próximos compromissos sem perder o controle.':page==='contas'?'Vamos manter cada conta no seu lugar.':page==='dividas'?'Aqui você acompanha compromissos de dívida sem misturar isso com suas despesas do dia a dia.':'Estou por aqui para ajudar, sem julgamentos.';return <div className="mascot-float"><button className="mascot-float-btn" onClick={()=>setOpen(!open)}>{mascot.emoji}</button>{open&&<div className="mascot-pop"><div className="mascot-pop-head"><span>{mascot.name}</span><button onClick={()=>setOpen(false)}><X size={14}/></button></div><p>{text}</p></div>}</div>}

function PageHeader({eyebrow,title,text,action}:{eyebrow:string;title:string;text:string;action?:React.ReactNode}){return <div className="page-intro"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{text}</p></div>{action}</div>}

function Home({mascot,user,onNavigate}:{mascot:Mascot;user:User;onNavigate:(p:Page)=>void}){const [data,setData]=useState<Dashboard|null>(null);const load=()=>api.dashboard().then(setData).catch(()=>{});useEffect(()=>{load()},[]);if(!data)return <div className="loading-screen">🌿</div>;const max=Math.max(1,...data.trend.flatMap(x=>[x.income,x.expense]));const totalCat=Math.max(1,data.categories.reduce((a,x)=>a+x.total,0));return <section className="page-section"><div className="welcome-row"><div><span className="eyebrow">BOM DIA, {String(user.nome||'VOCÊ').split(' ')[0].toUpperCase()}</span><h1>Seu dinheiro, com mais calma.</h1><p>Aqui está um resumo do que está acontecendo.</p></div><div className="welcome-mascot"><span>{mascot.emoji}</span><div><strong>{mascot.name}</strong><small>{mascot.personality}</small></div></div></div><div className="metric-grid"><Metric label="Saldo disponível" value={brl(data.balance)} icon={<CircleDollarSign/>} tone="green"/><Metric label="Entradas no mês" value={brl(data.month.income)} icon={<ArrowDownLeft/>} tone="blue"/><Metric label="Saídas no mês" value={brl(data.month.expense)} icon={<ArrowUpRight/>} tone="rose"/><Metric label="Resultado do mês" value={brl(data.month.income-data.month.expense)} icon={<BarChart3/>} tone="lavender"/></div><div className="dashboard-grid"><section className="panel trend-panel"><div className="panel-head"><div><span className="eyebrow">VISÃO GERAL</span><h3>Evolução financeira</h3></div><span className="tiny-pill">6 meses</span></div><div className="bar-chart">{data.trend.map(x=><div className="bar-col" key={x.mes}><div className="bars"><span style={{height:`${Math.max(4,x.income/max*100)}%`}} className="income-bar"/><span style={{height:`${Math.max(4,x.expense/max*100)}%`}} className="expense-bar"/></div><small>{new Date(`${x.mes}-15`).toLocaleDateString('pt-BR',{month:'short'}).replace('.','')}</small></div>)}</div><div className="chart-legend"><span><i className="dot income-dot"/> Entradas</span><span><i className="dot expense-dot"/> Saídas</span></div></section><section className="panel"><div className="panel-head"><div><span className="eyebrow">ATENÇÃO</span><h3>Próximos pagamentos</h3></div><button className="text-btn" onClick={()=>onNavigate('recorrencias')}>Ver todos <ChevronRight size={14}/></button></div>{data.upcoming.length?data.upcoming.slice(0,5).map(p=><div className="list-row" key={p.id}><div className={`row-icon ${p.tipo==='receita'?'income-bg':'expense-bg'}`}>{p.tipo==='receita'?<ArrowDownLeft size={16}/>:<CalendarClock size={16}/>}</div><div><strong>{p.nome}</strong><small>{dateBR(p.data_prevista)}</small></div><div className="row-right"><b>{brl(p.valor_previsto)}</b><small className={p.status==='atrasado'?'danger-text':''}>{p.status==='atrasado'?'Atrasada':'A vencer'}</small></div></div>):<div className="empty-state">Nada urgente por aqui. 🌿</div>}</section><section className="panel"><div className="panel-head"><div><span className="eyebrow">GASTOS</span><h3>Onde foi seu dinheiro</h3></div><button className="text-btn" onClick={()=>onNavigate('lancamentos')}>Detalhes <ChevronRight size={14}/></button></div>{data.categories.length?data.categories.map(c=><div className="category-line" key={c.categoria}><div><span>{c.categoria}</span><small>{Math.round(c.total/totalCat*100)}%</small></div><div className="progress"><span style={{width:`${Math.max(3,c.total/totalCat*100)}%`}}/></div><b>{brl(c.total)}</b></div>):<div className="empty-state">Ainda não há despesas neste mês.</div>}</section><section className="panel"><div className="panel-head"><div><span className="eyebrow">SUAS CONTAS</span><h3>Onde está seu dinheiro</h3></div><button className="text-btn" onClick={()=>onNavigate('contas')}>Gerenciar <ChevronRight size={14}/></button></div>{data.accounts.slice(0,4).map(a=><div className="list-row" key={a.id}><div className="row-icon neutral-bg"><Landmark size={16}/></div><div><strong>{a.nome}</strong><small>{accountLabel(a.tipo)}</small></div><div className="row-right"><b>{brl(a.saldo_atual)}</b></div></div>)}</section></div>{data.intelligence&&<div className="intelligence-grid"><div className="intelligence-card"><div className="intel-icon"><Activity size={18}/></div><span className="eyebrow">PROJEÇÃO DO MÊS</span><div className="intel-value">{brl(data.intelligence.projected_month.result)}</div><p>Resultado estimado até o fim do mês, usando o ritmo atual como referência.</p></div><div className="intelligence-card"><div className="intel-icon"><CalendarClock size={18}/></div><span className="eyebrow">PRÓXIMOS 30 DIAS</span><div className="intel-value">{brl(data.intelligence.projected_30_days_balance)}</div><p>Saldo projetado considerando compromissos previstos e a média recente.</p></div><div className="intelligence-card"><div className="intel-icon"><Target size={18}/></div><span className="eyebrow">PERCEPÇÕES</span><div className="intel-value">{data.intelligence.savings_rate.toFixed(1).replace('.',',')}%</div><p>Relação entre entradas e saídas pagas no mês até agora.</p></div></div>}{data.intelligence&&data.intelligence.category_signals.length>0&&<div className="insight-card"><div className="insight-mascot">{mascot.emoji}</div><div><span className="eyebrow">UMA PERCEPÇÃO</span><p>Alguns gastos deste mês estão acima da média recente. Isso é só um sinal para você decidir se vale olhar mais de perto.</p><div className="insight-list">{data.intelligence.category_signals.map(x=><div className="insight-item" key={x.categoria}><strong>{x.categoria}</strong>{brl(x.atual)} no mês · média anterior {brl(x.media_anterior)}</div>)}</div></div><button className="soft-btn" onClick={()=>onNavigate('lancamentos')}>Ver lançamentos</button></div>}{data.insights.length>0&&<div className="insight-card"><div className="insight-mascot">{mascot.emoji}</div><div><span className="eyebrow">PADRÕES</span><p>Há repetições no seu histórico que podem virar sugestões de organização. Nada é criado automaticamente.</p></div><button className="soft-btn" onClick={()=>onNavigate('lancamentos')}>Ver lançamentos</button></div>}</section>}
function Metric({label,value,icon,tone}:{label:string;value:string;icon:React.ReactNode;tone:string}){return <div className={`metric-card ${tone}`}><div className="metric-icon">{icon}</div><span>{label}</span><strong>{value}</strong></div>}
function accountLabel(t:string){return ({corrente:'Conta corrente',poupanca:'Poupança',carteira:'Carteira',investimento:'Investimentos',outro:'Outra conta'} as any)[t]||t}

function TransactionsPage(){const [items,setItems]=useState<Transaction[]>([]),[q,setQ]=useState(''),[filter,setFilter]=useState('todos'),[show,setShow]=useState(false);const load=()=>api.transactions().then(setItems);useEffect(()=>{load()},[]);const filtered=items.filter(x=>(filter==='todos'||x.tipo===filter)&&(!q||`${x.descricao} ${x.categoria_nome||''} ${x.conta_nome||''}`.toLowerCase().includes(q.toLowerCase())));return <section className="page-section"><PageHeader eyebrow="HISTÓRICO" title="Lançamentos" text="Tudo que já aconteceu com seu dinheiro, em um só lugar." action={<button className="primary-btn" onClick={()=>setShow(true)}><Plus size={16}/> Novo lançamento</button>}/><div className="toolbar"><div className="search-box"><Search size={16}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Buscar lançamentos..."/></div><div className="filter-pills">{[['todos','Todos'],['despesa','Despesas'],['receita','Receitas']].map(([v,l])=><button key={v} className={filter===v?'selected':''} onClick={()=>setFilter(v)}>{l}</button>)}</div></div><div className="panel table-panel">{filtered.length?filtered.map(x=><div className="transaction-row" key={x.id}><div className={`row-icon ${x.tipo==='receita'?'income-bg':'expense-bg'}`}>{x.tipo==='receita'?<ArrowDownLeft size={16}/>:<ArrowUpRight size={16}/>}</div><div className="tx-main"><strong>{x.descricao}</strong><small>{x.categoria_nome||'Sem categoria'} · {x.conta_nome||'Conta'}</small></div><div className="tx-date">{dateBR(x.data_movimento)}</div><strong className={x.tipo==='receita'?'positive':'negative'}>{x.tipo==='receita'?'+':'-'} {brl(x.valor)}</strong></div>):<div className="empty-state">Nenhum lançamento encontrado.</div>}</div>{show&&<TransactionModal onClose={()=>setShow(false)} onSaved={()=>{setShow(false);load()}}/>}</section>}

function TransactionModal({onClose,onSaved}:{onClose:()=>void;onSaved:()=>void}){
 const [accounts,setAccounts]=useState<Account[]>([]),[cats,setCats]=useState<Category[]>([]),[tipo,setTipo]=useState<'despesa'|'receita'>('despesa'),[valor,setValor]=useState(''),[descricao,setDescricao]=useState(''),[conta,setConta]=useState(''),[cat,setCat]=useState(''),[date,setDate]=useState(new Date().toISOString().slice(0,10)),[confirmed,setConfirmed]=useState(false),[error,setError]=useState(''),[suggestion,setSuggestion]=useState<any|null>(null),[suggestLoading,setSuggestLoading]=useState(false);
 useEffect(()=>{Promise.all([api.accounts(),api.categories()]).then(([a,c])=>{setAccounts(a.filter(x=>x.ativa));setCats(c);if(a[0])setConta(a[0].id)})},[]);
 useEffect(()=>{let cancelled=false;setSuggestion(null);if(descricao.trim().length<3)return;setSuggestLoading(true);const timer=setTimeout(()=>{api.launchSuggestions(descricao,tipo).then(r=>{if(!cancelled)setSuggestion(r.suggestions?.[0]||null)}).catch(()=>{}).finally(()=>{if(!cancelled)setSuggestLoading(false)})},350);return()=>{cancelled=true;clearTimeout(timer)}},[descricao,tipo]);
 function applySuggestion(){if(!suggestion)return;if(suggestion.categoria_id)setCat(suggestion.categoria_id);if(!valor&&suggestion.valor_medio)setValor(String(suggestion.valor_medio).replace('.',','));}
 async function save(e:React.FormEvent){e.preventDefault();if(!confirmed){setError('Confirme antes de registrar esta movimentação.');return}try{await api.createTransaction({tipo,valor:Number(valor.replace(',','.')),descricao,conta_id:conta,categoria_id:cat||null,data_movimento:date,status:'pago',confirmado:true});onSaved()}catch(e){setError(e instanceof Error?e.message:'Não foi possível salvar')}}
 return <Modal onClose={onClose}><span className="eyebrow">NOVO LANÇAMENTO</span><h3>Registrar movimentação</h3><p className="modal-note">O sistema pode sugerir categoria e valor com base no seu histórico. Você decide o que aplicar.</p><div className="segmented"><button type="button" className={tipo==='despesa'?'on':''} onClick={()=>setTipo('despesa')}>Despesa</button><button type="button" className={tipo==='receita'?'on':''} onClick={()=>setTipo('receita')}>Receita</button></div><form onSubmit={save}><label>Descrição<input autoFocus required value={descricao} onChange={e=>setDescricao(e.target.value)} placeholder="Ex.: supermercado"/></label>{suggestLoading&&<div className="suggestion-hint">Procurando padrões no seu histórico…</div>}{suggestion&&<div className="smart-suggestion"><div><span className="eyebrow">SUGESTÃO DO MEU CONTROLE</span><strong>{suggestion.categoria_nome||'Categoria não definida'}</strong><small>{suggestion.origem==='memoria'?(suggestion.ocorrencias?`Baseada em ${suggestion.ocorrencias} ocorrência(s)${suggestion.valor_medio?' · média '+brl(suggestion.valor_medio):''}.`:'Baseada no seu histórico.'):'Sugestão inicial baseada na descrição.'}</small></div><button type="button" className="soft-btn" onClick={applySuggestion}>Aplicar</button></div>}<label>Valor<input required inputMode="decimal" value={valor} onChange={e=>setValor(e.target.value)} placeholder="R$ 0,00"/></label><div className="two"><label>Categoria<select value={cat} onChange={e=>setCat(e.target.value)}><option value="">Sem categoria</option>{cats.filter(c=>c.tipo===tipo).map(c=><option key={c.id} value={c.id}>{c.nome}</option>)}</select></label><label>Conta<select required value={conta} onChange={e=>setConta(e.target.value)}>{accounts.map(a=><option key={a.id} value={a.id}>{a.nome}</option>)}</select></label></div><label>Data<input type="date" required value={date} onChange={e=>setDate(e.target.value)}/></label><label className="check-line"><input type="checkbox" checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/> Eu confirmo que quero registrar esta movimentação.</label>{error&&<div className="form-error">{error}</div>}<div className="confirm-actions"><button type="button" className="soft-btn" onClick={onClose}>Cancelar</button><button className="primary-btn">Salvar <Check size={16}/></button></div></form></Modal>}

function AccountsPage(){const [items,setItems]=useState<Account[]>([]),[show,setShow]=useState(false);const load=()=>api.accounts().then(setItems);useEffect(()=>{load()},[]);return <section className="page-section"><PageHeader eyebrow="ONDE ESTÁ SEU DINHEIRO" title="Contas" text="Organize bancos, carteira e poupança sem complicar." action={<button className="primary-btn" onClick={()=>setShow(true)}><Plus size={16}/> Nova conta</button>}/><div className="account-grid">{items.map(a=><div className="account-card" key={a.id}><div className="account-top"><div className="account-icon"><Landmark size={18}/></div><span>{accountLabel(a.tipo)}</span></div><h3>{a.nome}</h3><strong>{brl(a.saldo_atual)}</strong><small>Saldo atual</small></div>)}{!items.length&&<div className="empty-feature"><Wallet size={28}/><h3>Comece pela sua primeira conta</h3><p>Cadastre banco, carteira ou poupança para acompanhar o saldo.</p></div>}</div>{show&&<AccountModal onClose={()=>setShow(false)} onSaved={()=>{setShow(false);load()}}/>}</section>}
function AccountModal({onClose,onSaved}:{onClose:()=>void;onSaved:()=>void}){const [nome,setNome]=useState(''),[tipo,setTipo]=useState('corrente'),[saldo,setSaldo]=useState('0'),[error,setError]=useState('');async function save(e:React.FormEvent){e.preventDefault();try{await api.createAccount({nome,tipo,saldo_inicial:Number(saldo.replace(',','.'))});onSaved()}catch(e){setError(e instanceof Error?e.message:'Não foi possível criar')}}return <Modal onClose={onClose}><span className="eyebrow">NOVA CONTA</span><h3>Adicionar uma conta</h3><form onSubmit={save}><label>Nome<input required value={nome} onChange={e=>setNome(e.target.value)} placeholder="Ex.: Nubank"/></label><label>Tipo<select value={tipo} onChange={e=>setTipo(e.target.value)}><option value="corrente">Conta corrente</option><option value="poupanca">Poupança</option><option value="carteira">Carteira</option><option value="investimento">Investimentos</option><option value="outro">Outra</option></select></label><label>Saldo inicial<input inputMode="decimal" value={saldo} onChange={e=>setSaldo(e.target.value)}/></label>{error&&<div className="form-error">{error}</div>}<div className="confirm-actions"><button type="button" className="soft-btn" onClick={onClose}>Cancelar</button><button className="primary-btn">Criar conta <Check size={16}/></button></div></form></Modal>}

function RecurrencesPage(){const [items,setItems]=useState<Recurrence[]>([]),[payments,setPayments]=useState<Payment[]>([]),[summary,setSummary]=useState<RecurrenceSummary|null>(null),[show,setShow]=useState(false),[confirm,setConfirm]=useState<Payment|null>(null);const load=()=>Promise.all([api.recurrences(),api.payments(),api.recurrenceSummary()]).then(([r,p,s])=>{setItems(r);setPayments(p);setSummary(s)});useEffect(()=>{load()},[]);async function doConfirm(){if(!confirm)return;await api.confirmPayment(confirm.id,{confirmado:true,valor_real:confirm.valor_previsto,data_pagamento:new Date().toISOString().slice(0,10)});setConfirm(null);load()}return <section className="page-section"><PageHeader eyebrow="COMPROMISSOS" title="Recorrências" text="Contas que voltam aparecem aqui antes de virar movimentação real." action={<button className="primary-btn" onClick={()=>setShow(true)}><Plus size={16}/> Nova recorrência</button>}/><div className="content-grid"><section className="panel"><div className="panel-head"><div><span className="eyebrow">REGRAS</span><h3>Contas recorrentes</h3></div></div>{items.length?items.map(r=><div className="list-row" key={r.id}><div className="row-icon neutral-bg"><Repeat2 size={16}/></div><div><strong>{r.nome}</strong><small>{periodLabel(r.periodicidade)} · {r.valor_variavel?'valor variável':'valor fixo'}</small></div><div className="row-right"><b>{brl(r.valor)}</b></div></div>):<div className="empty-state">Nenhuma recorrência cadastrada.</div>}</section><section className="panel"><div className="panel-head"><div><span className="eyebrow">CONFIRMAÇÃO</span><h3>Pagamentos pendentes</h3></div></div>{payments.filter(p=>p.status!=='pago').slice(0,8).map(p=><div className="list-row" key={p.id}><div className="row-icon expense-bg"><CalendarClock size={16}/></div><div><strong>{p.nome}</strong><small>{dateBR(p.data_prevista)}</small></div><div className="row-right"><b>{brl(p.valor_previsto)}</b><button className="confirm-btn" onClick={()=>setConfirm(p)}>Confirmar</button></div></div>)}{!payments.filter(p=>p.status!=='pago').length&&<div className="empty-state">Nada esperando confirmação. 🌱</div>}</section></div>{summary&&<div className="content-grid" style={{marginTop:18}}><section className="panel"><div className="panel-head"><div><span className="eyebrow">VISÃO DOS PRÓXIMOS 90 DIAS</span><h3>Compromissos previstos</h3></div></div>{summary.proximos.slice(0,10).map(p=><div className="list-row" key={p.id}><div className="row-icon neutral-bg"><CalendarClock size={16}/></div><div><strong>{p.nome}</strong><small>{dateBR(p.data_prevista)} · {p.status==='atrasado'?'Atrasado':'Previsto'}</small></div><div className="row-right"><b>{p.valor_previsto==null?'Variável':brl(p.valor_previsto)}</b></div></div>)}{!summary.proximos.length&&<div className="empty-state">Nenhum compromisso previsto para os próximos 90 dias.</div>}</section><section className="panel"><div className="panel-head"><div><span className="eyebrow">HISTÓRICO REAL</span><h3>Comportamento das contas</h3></div></div>{summary.historico.filter(h=>h.ocorrencias>0).slice(0,8).map(h=><div className="list-row" key={h.recorrencia_id}><div className="row-icon neutral-bg"><Repeat2 size={16}/></div><div><strong>{h.nome}</strong><small>{h.ocorrencias} pagamento(s) · média {brl(h.media_real)}</small></div><div className="row-right"><small>{h.minimo_real>0?`${brl(h.minimo_real)} — ${brl(h.maximo_real)}`:''}</small></div></div>)}{!summary.historico.filter(h=>h.ocorrencias>0).length&&<div className="empty-state">Ainda não há histórico suficiente.</div>}</section></div>}{show&&<RecurrenceModal onClose={()=>setShow(false)} onSaved={()=>{setShow(false);load()}}/>}{confirm&&<ConfirmPayment p={confirm} onCancel={()=>setConfirm(null)} onConfirm={doConfirm}/>}</section>}
function RecurrenceModal({onClose,onSaved}:{onClose:()=>void;onSaved:()=>void}){const [accounts,setAccounts]=useState<Account[]>([]),[cats,setCats]=useState<Category[]>([]),[nome,setNome]=useState(''),[tipo,setTipo]=useState<'despesa'|'receita'>('despesa'),[valor,setValor]=useState(''),[conta,setConta]=useState(''),[cat,setCat]=useState(''),[period,setPeriod]=useState('mensal'),[variable,setVariable]=useState(false),[confirmed,setConfirmed]=useState(false),[date,setDate]=useState(new Date().toISOString().slice(0,10)),[day,setDay]=useState(''),[error,setError]=useState('');useEffect(()=>{Promise.all([api.accounts(),api.categories()]).then(([a,c])=>{setAccounts(a.filter(x=>x.ativa));setCats(c);if(a[0])setConta(a[0].id)})},[]);async function save(e:React.FormEvent){e.preventDefault();if(!confirmed){setError('Confirme antes de criar este compromisso recorrente.');return}try{await api.createRecurrence({nome,tipo,valor:Number(valor.replace(',','.')),valor_variavel:variable,periodicidade:period,conta_id:conta,categoria_id:cat||null,data_inicio:date,dia_cobranca:day?Number(day):null,gerar_automaticamente:true,confirmado:true});onSaved()}catch(e){setError(e instanceof Error?e.message:'Não foi possível criar')}}return <Modal onClose={onClose}><span className="eyebrow">NOVA RECORRÊNCIA</span><h3>Adicionar compromisso</h3><p className="modal-note">Nada será lançado como pago agora. O próximo pagamento fica aguardando sua confirmação.</p><form onSubmit={save}><label>Nome<input required value={nome} onChange={e=>setNome(e.target.value)} placeholder="Ex.: aluguel"/></label><div className="two"><label>Tipo<select value={tipo} onChange={e=>setTipo(e.target.value as any)}><option value="despesa">Saída</option><option value="receita">Entrada</option></select></label><label>Valor<input required inputMode="decimal" value={valor} onChange={e=>setValor(e.target.value)} placeholder="0,00"/></label></div><div className="two"><label>Periodicidade<select value={period} onChange={e=>setPeriod(e.target.value)}><option value="semanal">Semanal</option><option value="quinzenal">Quinzenal</option><option value="mensal">Mensal</option><option value="bimestral">Bimestral</option><option value="trimestral">Trimestral</option><option value="semestral">Semestral</option><option value="anual">Anual</option><option value="personalizada">Personalizada</option></select></label><label>Dia<input type="number" min="1" max="31" value={day} onChange={e=>setDay(e.target.value)} placeholder="Opcional"/></label></div><label>Início<input type="date" value={date} onChange={e=>setDate(e.target.value)} required/></label><label>Conta<select value={conta} onChange={e=>setConta(e.target.value)} required>{accounts.map(a=><option key={a.id} value={a.id}>{a.nome}</option>)}</select></label><label>Categoria<select value={cat} onChange={e=>setCat(e.target.value)}><option value="">Sem categoria</option>{cats.filter(c=>c.tipo===tipo).map(c=><option key={c.id} value={c.id}>{c.nome}</option>)}</select></label><label className="check-line"><input type="checkbox" checked={variable} onChange={e=>setVariable(e.target.checked)}/> O valor pode variar</label><label className="check-line"><input type="checkbox" checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/> Eu confirmo a criação deste compromisso recorrente.</label>{error&&<div className="form-error">{error}</div>}<div className="confirm-actions"><button type="button" className="soft-btn" onClick={onClose}>Cancelar</button><button className="primary-btn">Criar recorrência <Check size={16}/></button></div></form></Modal>}
function ConfirmPayment({p,onCancel,onConfirm}:{p:Payment;onCancel:()=>void;onConfirm:()=>void}){return <Modal onClose={onCancel}><div className="confirm-mark">✓</div><span className="eyebrow">CONFIRMAÇÃO NECESSÁRIA</span><h3>Registrar este pagamento?</h3><p>Isso criará uma movimentação financeira real no histórico.</p><div className="confirm-box"><div><span>Compromisso</span><strong>{p.nome}</strong></div><div><span>Valor</span><strong>{brl(p.valor_previsto)}</strong></div><div><span>Data</span><strong>{dateBR(p.data_prevista)}</strong></div></div><div className="confirm-actions"><button className="soft-btn" onClick={onCancel}>Voltar</button><button className="primary-btn" onClick={onConfirm}>Sim, confirmar <Check size={16}/></button></div></Modal>}

function DebtsPage(){const [items,setItems]=useState<any[]>([]),[summary,setSummary]=useState<any>(null),[show,setShow]=useState(false),[selected,setSelected]=useState<any>(null);const load=()=>Promise.all([api.debts(),api.debtSummary()]).then(([a,b])=>{setItems(a);setSummary(b)});useEffect(()=>{load()},[]);return <section className="page-section"><PageHeader eyebrow="COMPROMISSOS" title="Dívidas" text="Acompanhe saldo devedor e parcelas sem transformar o controle em julgamento." action={<button className="primary-btn" onClick={()=>setShow(true)}><Plus size={16}/> Nova dívida</button>}/><div className="planning-summary"><div className="planning-card"><span>SALDO DEVEDOR</span><strong>{brl(summary?.saldo||0)}</strong><small>valor ainda registrado como devido</small></div><div className="planning-card"><span>PARCELAS MENSAIS</span><strong>{brl(summary?.parcelas_mensais||0)}</strong><small>soma das parcelas informadas</small></div><div className="planning-card"><span>COMPROMISSOS</span><strong>{summary?.quantidade||0}</strong><small>dívidas ativas cadastradas</small></div></div><div className="debt-grid">{items.map(d=>{const pct=d.valor_original?Math.min(100,Math.max(0,(1-d.saldo_devedor/d.valor_original)*100)):0;return <div className="debt-card" key={d.id}><div className="debt-head"><div><span className="eyebrow">{d.tipo}</span><h3>{d.nome}</h3><small>{d.credor||'Credor não informado'}</small></div><HandCoins size={24}/></div><div className="debt-values"><div><span>Saldo devedor</span><b>{brl(d.saldo_devedor)}</b></div><div><span>Original</span><b>{brl(d.valor_original)}</b></div></div><div className="report-progress"><span style={{width:`${pct}%`}}/></div><small>{Math.round(pct)}% do valor original já não está no saldo devedor</small><div className="debt-foot"><span>Parcela {d.parcela_atual?brl(d.parcela_atual):'—'}</span><span>{d.parcelas_restantes?`${d.parcelas_restantes} restantes`:'—'}</span></div><button className="soft-btn wide" onClick={()=>setSelected(d)}>Atualizar saldo</button></div>})}{!items.length&&<div className="empty-feature"><HandCoins size={28}/><h3>Nenhuma dívida cadastrada</h3><p>Cadastre empréstimos, financiamentos ou parcelamentos para acompanhar o saldo.</p></div>}</div>{show&&<DebtModal onClose={()=>setShow(false)} onSaved={()=>{setShow(false);load()}}/>}{selected&&<DebtUpdate debt={selected} onClose={()=>setSelected(null)} onSaved={()=>{setSelected(null);load()}}/>}</section>}
function DebtModal({onClose,onSaved}:{onClose:()=>void;onSaved:()=>void}){const [nome,setNome]=useState(''),[credor,setCredor]=useState(''),[tipo,setTipo]=useState('emprestimo'),[orig,setOrig]=useState(''),[saldo,setSaldo]=useState(''),[parcela,setParcela]=useState(''),[rest,setRest]=useState(''),[confirm,setConfirm]=useState(false),[error,setError]=useState('');async function save(e:React.FormEvent){e.preventDefault();if(!confirm){setError('Confirme antes de cadastrar esta dívida.');return}try{await api.createDebt({nome,credor,tipo,valor_original:Number(orig.replace(',','.')),saldo_devedor:Number(saldo.replace(',','.')),parcela_atual:parcela?Number(parcela.replace(',','.')):null,parcelas_restantes:rest?Number(rest):null,confirmado:true});onSaved()}catch(e){setError(e instanceof Error?e.message:'Não foi possível cadastrar')}}return <Modal onClose={onClose}><span className="eyebrow">NOVA DÍVIDA</span><h3>Cadastrar compromisso</h3><form onSubmit={save}><label>Nome<input required value={nome} onChange={e=>setNome(e.target.value)} placeholder="Ex.: Empréstimo pessoal"/></label><label>Credor<input value={credor} onChange={e=>setCredor(e.target.value)} placeholder="Ex.: Banco"/></label><div className="two"><label>Tipo<select value={tipo} onChange={e=>setTipo(e.target.value)}><option value="emprestimo">Empréstimo</option><option value="financiamento">Financiamento</option><option value="parcelamento">Parcelamento</option><option value="outro">Outro</option></select></label><label>Valor original<input required inputMode="decimal" value={orig} onChange={e=>setOrig(e.target.value)} placeholder="0,00"/></label></div><div className="two"><label>Saldo devedor<input required inputMode="decimal" value={saldo} onChange={e=>setSaldo(e.target.value)} placeholder="0,00"/></label><label>Parcela mensal<input inputMode="decimal" value={parcela} onChange={e=>setParcela(e.target.value)} placeholder="Opcional"/></label></div><label>Parcelas restantes<input type="number" min="0" value={rest} onChange={e=>setRest(e.target.value)} placeholder="Opcional"/></label><label className="check-line"><input type="checkbox" checked={confirm} onChange={e=>setConfirm(e.target.checked)}/> Eu confirmo o cadastro desta dívida.</label>{error&&<div className="form-error">{error}</div>}<div className="confirm-actions"><button type="button" className="soft-btn" onClick={onClose}>Cancelar</button><button className="primary-btn">Cadastrar <Check size={16}/></button></div></form></Modal>}
function DebtUpdate({debt,onClose,onSaved}:{debt:any;onClose:()=>void;onSaved:()=>void}){const [saldo,setSaldo]=useState(String(debt.saldo_devedor)),[parcela,setParcela]=useState(debt.parcela_atual==null?'':String(debt.parcela_atual)),[rest,setRest]=useState(debt.parcelas_restantes==null?'':String(debt.parcelas_restantes)),[confirm,setConfirm]=useState(false),[error,setError]=useState('');async function save(e:React.FormEvent){e.preventDefault();if(!confirm){setError('Confirme antes de atualizar o saldo.');return}try{await api.updateDebt(debt.id,{saldo_devedor:Number(saldo.replace(',','.')),parcela_atual:parcela?Number(parcela.replace(',','.')):null,parcelas_restantes:rest?Number(rest):null,confirmado:true});onSaved()}catch(e){setError(e instanceof Error?e.message:'Não foi possível atualizar')}}return <Modal onClose={onClose}><span className="eyebrow">ATUALIZAR DÍVIDA</span><h3>{debt.nome}</h3><form onSubmit={save}><label>Novo saldo devedor<input required inputMode="decimal" value={saldo} onChange={e=>setSaldo(e.target.value)}/></label><label>Parcela mensal<input inputMode="decimal" value={parcela} onChange={e=>setParcela(e.target.value)}/></label><label>Parcelas restantes<input type="number" min="0" value={rest} onChange={e=>setRest(e.target.value)}/></label><label className="check-line"><input type="checkbox" checked={confirm} onChange={e=>setConfirm(e.target.checked)}/> Eu confirmo esta atualização.</label>{error&&<div className="form-error">{error}</div>}<div className="confirm-actions"><button type="button" className="soft-btn" onClick={onClose}>Cancelar</button><button className="primary-btn">Salvar <Check size={16}/></button></div></form></Modal>}
function CardsPage(){const [items,setItems]=useState<Card[]>([]),[show,setShow]=useState(false),[selected,setSelected]=useState<Card|null>(null),[purchase,setPurchase]=useState(false);const load=()=>api.cards().then(setItems);useEffect(()=>{load()},[]);return <section className="page-section"><PageHeader eyebrow="COMPRAS FUTURAS" title="Cartões" text="Limites, fechamento e parcelas em um lugar só." action={<button className="primary-btn" onClick={()=>setShow(true)}><Plus size={16}/> Novo cartão</button>}/><div className="card-grid">{items.map(c=><div className="credit-card" key={c.id}><div className="credit-top"><span>{c.banco||'Cartão'}</span><CreditCard size={20}/></div><h3>{c.nome}</h3><strong>{c.limite==null?'Sem limite informado':brl(c.disponivel??0)}</strong><small>{c.limite==null?'Limite não informado':`disponível de ${brl(c.limite)}`}</small><div className="card-progress"><span style={{width:c.limite?`${Math.min(100,c.comprometido/c.limite*100)}%`:'0%'}}/></div><div className="credit-foot"><span>Comprometido {brl(c.comprometido)}</span><span>Venc. dia {c.dia_vencimento||'—'}</span></div><button className="card-action" onClick={()=>{setSelected(c);setPurchase(true)}}>Registrar compra <ChevronRight size={14}/></button></div>)}{!items.length&&<div className="empty-feature"><CreditCard size={28}/><h3>Nenhum cartão cadastrado</h3><p>Cadastre um cartão para acompanhar limite e parcelas.</p></div>}</div>{show&&<CardModal onClose={()=>setShow(false)} onSaved={()=>{setShow(false);load()}}/>}{purchase&&selected&&<PurchaseModal card={selected} onClose={()=>setPurchase(false)} onSaved={()=>{setPurchase(false);load()}}/>}</section>}
function CardModal({onClose,onSaved}:{onClose:()=>void;onSaved:()=>void}){const [nome,setNome]=useState(''),[banco,setBanco]=useState(''),[limite,setLimite]=useState(''),[fech,setFech]=useState(''),[venc,setVenc]=useState('');async function save(e:React.FormEvent){e.preventDefault();await api.createCard({nome,banco,limite:Number(limite.replace(',','.')),dia_fechamento:Number(fech)||null,dia_vencimento:Number(venc)||null});onSaved()}return <Modal onClose={onClose}><span className="eyebrow">NOVO CARTÃO</span><h3>Cadastrar cartão</h3><form onSubmit={save}><label>Nome<input required value={nome} onChange={e=>setNome(e.target.value)} placeholder="Ex.: Nubank"/></label><label>Banco<input value={banco} onChange={e=>setBanco(e.target.value)} placeholder="Ex.: Nubank"/></label><label>Limite<input required inputMode="decimal" value={limite} onChange={e=>setLimite(e.target.value)} placeholder="0,00"/></label><div className="two"><label>Fechamento<input type="number" min="1" max="31" value={fech} onChange={e=>setFech(e.target.value)}/></label><label>Vencimento<input type="number" min="1" max="31" value={venc} onChange={e=>setVenc(e.target.value)}/></label></div><div className="confirm-actions"><button type="button" className="soft-btn" onClick={onClose}>Cancelar</button><button className="primary-btn">Salvar cartão <Check size={16}/></button></div></form></Modal>}
function PurchaseModal({card,onClose,onSaved}:{card:Card;onClose:()=>void;onSaved:()=>void}){const [desc,setDesc]=useState(''),[valor,setValor]=useState(''),[parcelas,setParcelas]=useState('1'),[date,setDate]=useState(new Date().toISOString().slice(0,10)),[confirmed,setConfirmed]=useState(false),[preview,setPreview]=useState<any>(null),[error,setError]=useState(''),[loading,setLoading]=useState(false);async function makePreview(){setError('');setLoading(true);try{const p=await api.previewCardPurchase({cartao_id:card.id,descricao:desc,valor_total:Number(valor.replace(',','.')),numero_parcelas:Number(parcelas),data_compra:date});setPreview(p)}catch(e){setPreview(null);setError(e instanceof Error?e.message:'Não foi possível calcular a prévia')}finally{setLoading(false)}}async function save(e:React.FormEvent){e.preventDefault();if(!preview){await makePreview();return}if(!confirmed){setError('Marque a confirmação para registrar este compromisso.');return}try{await api.createCardPurchase({cartao_id:card.id,descricao:desc,valor_total:Number(valor.replace(',','.')),numero_parcelas:Number(parcelas),data_compra:date,confirmado:true});onSaved()}catch(e){setError(e instanceof Error?e.message:'Não foi possível registrar')}}return <Modal onClose={onClose}><span className="eyebrow">NOVA COMPRA</span><h3>Registrar no {card.nome}</h3><p className="modal-note">Primeiro veja o impacto no limite e nas próximas faturas. Nada é gravado durante a prévia.</p><form onSubmit={save}><label>Descrição<input required value={desc} onChange={e=>{setDesc(e.target.value);setPreview(null)}} placeholder="Ex.: celular"/></label><div className="two"><label>Valor total<input required inputMode="decimal" value={valor} onChange={e=>{setValor(e.target.value);setPreview(null)}} placeholder="0,00"/></label><label>Parcelas<input type="number" min="1" max="60" value={parcelas} onChange={e=>{setParcelas(e.target.value);setPreview(null)}}/></label></div><label>Data da compra<input type="date" required value={date} onChange={e=>{setDate(e.target.value);setPreview(null)}}/></label>{preview&&<div className="preview-card"><strong>Prévia do compromisso</strong><span>Total {brl(preview.compra.valor_total)} · {preview.compra.numero_parcelas}x de aprox. {brl(preview.parcelas[0]?.valor)}</span><span>Limite disponível após a compra: {preview.cartao.disponivel==null?'não informado':brl(preview.cartao.disponivel)}</span><small>1ª parcela: {preview.parcelas[0]?.data_vencimento} · última: {preview.parcelas.at(-1)?.data_vencimento}</small></div>}{preview&&<label className="check-line"><input type="checkbox" checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/> Eu confirmo que quero registrar esta compra e criar as parcelas.</label>}{error&&<div className="form-error">{error}</div>}<div className="confirm-actions"><button type="button" className="soft-btn" onClick={onClose}>Cancelar</button><button className="primary-btn" disabled={loading}>{preview?(confirmed?'Registrar compra':'Confirmar para registrar'):(loading?'Calculando…':'Ver impacto da compra')} <Check size={16}/></button></div></form></Modal>}

function InvestmentsPage(){
 const [items,setItems]=useState<Investment[]>([]),[summary,setSummary]=useState<InvestmentSummary|null>(null),[accounts,setAccounts]=useState<Account[]>([]),[show,setShow]=useState(false),[selected,setSelected]=useState<Investment|null>(null);
 const load=async()=>{const [i,s,a]=await Promise.all([api.investments(),api.investmentSummary(),api.accounts()]);setItems(i);setSummary(s);setAccounts(a)};
 useEffect(()=>{load()},[]);
 const gain=(i:Investment)=>i.valor_atual-i.valor_investido;
 return <section className="page-section">
  <PageHeader eyebrow="PATRIMÔNIO" title="Investimentos" text="Acompanhe o que está investido, o valor atual e a evolução da carteira." action={<button className="primary-btn" onClick={()=>setShow(true)}><Plus size={16}/> Novo investimento</button>}/>
  {summary&&<div className="planning-summary"><div className="planning-card"><span>VALOR INVESTIDO</span><strong>{brl(summary.investido)}</strong><small>capital registrado na carteira</small></div><div className="planning-card"><span>VALOR ATUAL</span><strong>{brl(summary.atual)}</strong><small>posição informada atualmente</small></div><div className="planning-card"><span>RESULTADO</span><strong>{brl(summary.ganho)}</strong><small>diferença entre valor atual e investido</small></div></div>}
  <div className="investment-grid">
   {items.map(i=><div className="investment-card" key={i.id}><div className="investment-head"><div><strong>{i.nome}</strong><small>{i.tipo}{i.instituicao?` · ${i.instituicao}`:''}</small></div><TrendingUp size={20}/></div><div className="investment-values"><span>Investido <b>{brl(i.valor_investido)}</b></span><span>Atual <b>{brl(i.valor_atual)}</b></span></div><div className={`investment-result ${gain(i)>=0?'positive':'negative'}`}>{gain(i)>=0?'▲':'▼'} {brl(Math.abs(gain(i)))} de diferença</div><small>{i.conta_nome?`Conta: ${i.conta_nome}`:'Sem conta vinculada'}{i.data_vencimento?` · vence ${dateBR(i.data_vencimento)}`:''}</small><button className="soft-btn wide" onClick={()=>setSelected(i)}>Atualizar valor</button></div>)}
   {!items.length&&<div className="empty-feature"><TrendingUp size={28}/><h3>Sua carteira ainda está vazia</h3><p>Cadastre investimentos para acompanhar patrimônio e evolução. Registrar um investimento não movimenta sua conta.</p></div>}
  </div>
  {show&&<InvestmentModal accounts={accounts} onClose={()=>setShow(false)} onSaved={()=>{setShow(false);load()}}/>}
  {selected&&<InvestmentUpdate investment={selected} onClose={()=>setSelected(null)} onSaved={()=>{setSelected(null);load()}}/>}
 </section>;
}
function InvestmentModal({accounts,onClose,onSaved}:{accounts:Account[];onClose:()=>void;onSaved:()=>void}){
 const [nome,setNome]=useState(''); const [tipo,setTipo]=useState('Renda fixa'); const [instituicao,setInstituicao]=useState(''); const [valor,setValor]=useState(''); const [conta_id,setContaId]=useState(''); const [saving,setSaving]=useState(false);
 async function save(e:React.FormEvent){e.preventDefault();setSaving(true);try{await api.createInvestment({nome,tipo,instituicao,valor_investido:Number(valor),valor_atual:Number(valor),conta_id:conta_id||undefined});onSaved()}finally{setSaving(false)}}
 return <Modal title="Novo investimento" onClose={onClose}><form onSubmit={save} className="modal-form"><label>Nome<input value={nome} onChange={e=>setNome(e.target.value)} required placeholder="Ex.: CDB"/></label><label>Tipo<input value={tipo} onChange={e=>setTipo(e.target.value)} required/></label><label>Instituição<input value={instituicao} onChange={e=>setInstituicao(e.target.value)} placeholder="Opcional"/></label><label>Valor investido<input type="number" step="0.01" min="0" value={valor} onChange={e=>setValor(e.target.value)} required/></label><label>Conta de referência<select value={conta_id} onChange={e=>setContaId(e.target.value)}><option value="">Nenhuma</option>{accounts.map(a=><option key={a.id} value={a.id}>{a.nome}</option>)}</select></label><button className="primary-btn" disabled={saving}>{saving?'Salvando...':'Salvar investimento'}<Check size={16}/></button></form></Modal>}
function InvestmentUpdate({investment,onClose,onSaved}:{investment:Investment;onClose:()=>void;onSaved:()=>void}){
 const [valor,setValor]=useState(String(investment.valor_atual)); const [saving,setSaving]=useState(false);
 async function save(e:React.FormEvent){e.preventDefault();setSaving(true);try{await api.updateInvestment(investment.id,{valor_atual:Number(valor)});onSaved()}finally{setSaving(false)}}
 return <Modal title="Atualizar investimento" onClose={onClose}><form onSubmit={save} className="modal-form"><p className="muted">{investment.nome}</p><label>Valor atual<input type="number" step="0.01" min="0" value={valor} onChange={e=>setValor(e.target.value)} required/></label><button className="primary-btn" disabled={saving}>{saving?'Salvando...':'Salvar atualização'}<Check size={16}/></button></form></Modal>}
function GoalsPage(){
 const [items,setItems]=useState<Goal[]>([]),[planning,setPlanning]=useState<any|null>(null),[accounts,setAccounts]=useState<Account[]>([]),[show,setShow]=useState(false),[selected,setSelected]=useState<Goal|null>(null);
 const load=async()=>{const [g,p,a]=await Promise.all([api.goals(),api.goalPlanning(),api.accounts()]);setItems(g);setPlanning(p);setAccounts(a)};
 useEffect(()=>{load()},[]);
 const fmtScenario=(d:string|null)=>d?dateBR(d):'Sem previsão';
 return <section className="page-section">
  <PageHeader eyebrow="SEUS PLANOS" title="Metas" text="Transforme objetivos em progresso visível, sem pressão." action={<button className="primary-btn" onClick={()=>setShow(true)}><Plus size={16}/> Nova meta</button>}/>
  {planning&&<><div className="planning-summary">
    <div className="planning-card"><span>CAPACIDADE MÉDIA</span><strong>{brl(planning.premissas.capacidade_mensal_atual)}</strong><small>potencial mensal após entradas e saídas recentes</small></div>
    <div className="planning-card"><span>PATRIMÔNIO ATUAL</span><strong>{brl(planning.premissas.patrimonio_atual)}</strong><small>saldo líquido das contas ativas</small></div>
    <div className="planning-card"><span>DESPESAS MÉDIAS</span><strong>{brl(planning.premissas.media_saidas)}</strong><small>média mensal usada na simulação</small></div>
  </div>
  <section className="panel planning-panel"><div className="panel-head"><div><span className="eyebrow">PLANEJAMENTO</span><h3>Quanto cada meta pede de você?</h3></div><span className="muted">Simulação, não movimentação</span></div>
   <div className="planning-grid">{planning.metas.map((g:any)=><div className="planning-goal" key={g.id}><div className="planning-goal-head"><div><strong>{g.nome}</strong><small>{g.conta_nome?`Conta: ${g.conta_nome}`:'Sem conta vinculada'} · {g.data_limite?`prazo ${dateBR(g.data_limite)}`:'sem prazo'}</small></div><b>{brl(g.restante)} faltando</b></div><div className="planning-required">{g.aporte_mensal_necessario!==null?`Aporte mensal necessário: ${brl(g.aporte_mensal_necessario)}`:'Defina um prazo para calcular o aporte mensal.'}</div><div className="scenario-row"><span>🐢 Conservador <b>{fmtScenario(g.cenarios.conservador)}</b></span><span>🌿 Atual <b>{fmtScenario(g.cenarios.atual)}</b></span><span>⚡ Acelerado <b>{fmtScenario(g.cenarios.acelerado)}</b></span></div></div>)}{!planning.metas.length&&<div className="empty-state">Crie uma meta para começar a simular seus próximos passos.</div>}</div>
  </section></>}
  <div className="goal-grid">{items.map(g=>{const pct=Math.min(100,g.valor_objetivo?g.valor_atual/g.valor_objetivo*100:0);return <div className="goal-card" key={g.id}><div className="goal-icon">🎯</div><div className="goal-head"><div><strong>{g.nome}</strong><small>{g.data_limite?`Até ${dateBR(g.data_limite)}`:'Sem prazo'}{g.conta_nome?` · ${g.conta_nome}`:''}</small></div><span>{Math.round(pct)}%</span></div><div className="goal-progress"><span style={{width:`${pct}%`}}/></div><div className="goal-values"><b>{brl(g.valor_atual)}</b><span>de {brl(g.valor_objetivo)}</span></div>{g.status==='ativa'&&<button className="soft-btn wide" onClick={()=>setSelected(g)}>Adicionar progresso</button>}</div>})}{!items.length&&<div className="empty-feature"><Target size={28}/><h3>Qual é o próximo objetivo?</h3><p>Crie uma meta para acompanhar uma viagem, reserva, compra ou outro plano.</p></div>}</div>
  {planning&&<section className="panel" style={{marginTop:18}}><div className="panel-head"><div><span className="eyebrow">PATRIMÔNIO</span><h3>Uma visão dos próximos 12 meses</h3></div></div><div className="wealth-projection">{planning.patrimonio_projetado.map((m:any)=><div className="wealth-point" key={m.mes}><small>{m.mes.slice(5)}/{m.mes.slice(0,4)}</small><div><span style={{height:`${Math.max(8,Math.min(100,(m.patrimonio_projetado/(planning.premissas.patrimonio_atual||1))*20))}%`}}/></div><b>{brl(m.patrimonio_projetado)}</b></div>)}</div><p className="modal-note">A projeção usa a capacidade média atual como hipótese. Ela não prevê rentabilidade de investimentos e não executa transferências.</p></section>}
  {show&&<GoalModal accounts={accounts} onClose={()=>setShow(false)} onSaved={()=>{setShow(false);load()}}/>}{selected&&<GoalContribution goal={selected} onClose={()=>setSelected(null)} onSaved={()=>{setSelected(null);load()}}/>}
 </section>}
function GoalModal({accounts,onClose,onSaved}:{accounts:Account[];onClose:()=>void;onSaved:()=>void}){const [nome,setNome]=useState(''),[objetivo,setObjetivo]=useState(''),[prazo,setPrazo]=useState(''),[conta,setConta]=useState('');async function save(e:React.FormEvent){e.preventDefault();await api.createGoal({nome,valor_objetivo:Number(objetivo.replace(',','.')),data_limite:prazo||null,conta_id:conta||null});onSaved()}return <Modal onClose={onClose}><span className="eyebrow">NOVA META</span><h3>Dar nome ao seu próximo plano</h3><form onSubmit={save}><label>Meta<input required value={nome} onChange={e=>setNome(e.target.value)} placeholder="Ex.: Reserva de emergência"/></label><label>Valor objetivo<input required inputMode="decimal" value={objetivo} onChange={e=>setObjetivo(e.target.value)} placeholder="0,00"/></label><label>Data limite<input type="date" value={prazo} onChange={e=>setPrazo(e.target.value)}/></label><label>Conta para acompanhar <select value={conta} onChange={e=>setConta(e.target.value)}><option value="">Nenhuma — apenas acompanhar</option>{accounts.map(a=><option key={a.id} value={a.id}>{a.nome}</option>)}</select></label><p className="modal-note">Vincular uma conta é apenas organizacional. Criar a meta não movimenta dinheiro.</p><div className="confirm-actions"><button type="button" className="soft-btn" onClick={onClose}>Cancelar</button><button className="primary-btn">Criar meta <Check size={16}/></button></div></form></Modal>}
function GoalContribution({goal,onClose,onSaved}:{goal:Goal;onClose:()=>void;onSaved:()=>void}){const [valor,setValor]=useState(''),[confirmed,setConfirmed]=useState(false),[error,setError]=useState('');async function save(e:React.FormEvent){e.preventDefault();if(!confirmed){setError('Confirme antes de registrar o progresso.');return}try{await api.contributeGoal(goal.id,{valor:Number(valor.replace(',','.')),confirmado:true});onSaved()}catch(e){setError(e instanceof Error?e.message:'Não foi possível atualizar')}}return <Modal onClose={onClose}><span className="eyebrow">PROGRESSO DA META</span><h3>{goal.nome}</h3><p className="modal-note">Este registro atualiza o progresso da meta. Ele não movimenta uma conta automaticamente.</p><form onSubmit={save}><label>Quanto adicionar?<input required inputMode="decimal" value={valor} onChange={e=>setValor(e.target.value)} placeholder="0,00"/></label><label className="check-line"><input type="checkbox" checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/> Eu confirmo este aporte no acompanhamento da meta.</label>{error&&<div className="form-error">{error}</div>}<div className="confirm-actions"><button type="button" className="soft-btn" onClick={onClose}>Cancelar</button><button className="primary-btn">Confirmar <Check size={16}/></button></div></form></Modal>}


function PrivacyPanel(){
 const [data,setData]=useState<any>(null),[kind,setKind]=useState('acesso'),[desc,setDesc]=useState(''),[message,setMessage]=useState(''),[error,setError]=useState('');
 useEffect(()=>{api.privacy().then(setData).catch(e=>setError(e instanceof Error?e.message:'Não foi possível carregar a privacidade.'))},[]);
 async function accept(){try{const r=await api.acceptPrivacy({tipo:'politica_privacidade',aceito:true,versao:'1.0'});setMessage(`Consentimento registrado — versão ${r.versao}.`);setData(await api.privacy())}catch(e){setError(e instanceof Error?e.message:'Não foi possível registrar o consentimento.')}}
 async function request(){try{await api.privacyRequest({tipo:kind,descricao:desc});setDesc('');setMessage('Solicitação registrada.');setData(await api.privacy())}catch(e){setError(e instanceof Error?e.message:'Não foi possível registrar a solicitação.')}}
 const accepted=data?.consentimentos?.some((x:any)=>x.tipo==='politica_privacidade'&&x.aceito&&x.versao_politica===data.versao_atual);
 return <div className="privacy-panel"><div className="security-title"><div><span className="eyebrow">PRIVACIDADE</span><h2>Seus dados, sob seu controle</h2><p>Veja o que o sistema guarda, registre seu consentimento e envie solicitações de privacidade.</p></div><Shield size={30}/></div>{message&&<div className="success-box">{message}</div>}{error&&<div className="form-error">{error}</div>}<div className="soft-card"><span>POLÍTICA DE PRIVACIDADE · VERSÃO {data?.versao_atual||'1.0'}</span><h3>O que armazenamos</h3><p className="modal-note">{data?.politica?.resumo||'Dados necessários para conta, segurança e funcionalidades solicitadas.'}</p><ul>{(data?.politica?.dados_principais||[]).map((x:string)=><li key={x}>{x}</li>)}</ul>{!accepted?<button className="primary-btn" onClick={accept}>Registrar meu consentimento <Check size={16}/></button>:<small>✓ Consentimento registrado para a versão atual.</small>}</div><div className="soft-card"><span>SEUS DIREITOS</span><h3>Enviar uma solicitação</h3><div className="two"><label>Tipo<select value={kind} onChange={e=>setKind(e.target.value)}><option value="acesso">Acesso aos dados</option><option value="correcao">Correção</option><option value="portabilidade">Portabilidade</option><option value="eliminacao">Eliminação</option><option value="outro">Outro</option></select></label><label>Descrição<textarea value={desc} onChange={e=>setDesc(e.target.value)} placeholder="Se quiser, explique o que precisa."/></label></div><button className="soft-btn" onClick={request}>Registrar solicitação</button>{data?.solicitacoes?.length>0&&<div className="session-list">{data.solicitacoes.slice(0,5).map((x:any)=><div className="session-item" key={x.id}><div><strong>{x.tipo}</strong><small>{x.status} · {new Date(x.criada_em).toLocaleString('pt-BR')}</small></div></div>)}</div>}</div></div>
}


function SecurityPanel({onAccountDeleted}:{onAccountDeleted:()=>void}){
 const [mfa,setMfa]=useState<any>(null),[sessions,setSessions]=useState<any[]>([]),[audit,setAudit]=useState<any[]>([]),[mfaSetup,setMfaSetup]=useState<any>(null),[code,setCode]=useState(''),[password,setPassword]=useState(''),[newPassword,setNewPassword]=useState(''),[mfaDisableCode,setMfaDisableCode]=useState(''),[showPassword,setShowPassword]=useState(false),[showDelete,setShowDelete]=useState(false),[deleteText,setDeleteText]=useState(''),[message,setMessage]=useState(''),[error,setError]=useState('');
 const load=()=>Promise.all([api.mfaStatus(),api.sessions(),api.audit()]).then(([a,b,c])=>{setMfa(a);setSessions(b);setAudit(c)}).catch(e=>setError(e instanceof Error?e.message:'Não foi possível carregar a segurança.'));
 useEffect(()=>{load()},[]);
 async function startMfa(){const p=window.prompt('Por segurança, confirme sua senha atual:');if(!p)return;setError('');try{const r=await api.startMfa(p);setMfaSetup(r)}catch(e){setError(e instanceof Error?e.message:'Não foi possível iniciar o MFA.')}}
 async function confirmMfa(){setError('');try{await api.confirmMfa(code);setMfaSetup(null);setCode('');setMessage('Autenticação em dois fatores ativada.');await load()}catch(e){setError(e instanceof Error?e.message:'Código inválido.')}}
 async function disableMfa(){setError('');try{await api.disableMfa({password,code:mfaDisableCode});setPassword('');setMfaDisableCode('');setMessage('MFA desativado.');await load()}catch(e){setError(e instanceof Error?e.message:'Não foi possível desativar o MFA.')}}
 async function changePassword(){setError('');try{await api.changePassword({senha_atual:password,nova_senha:newPassword,codigo_mfa:mfa?.mfa_enabled?mfaDisableCode:undefined});setPassword('');setNewPassword('');setMfaDisableCode('');setShowPassword(false);setMessage('Senha alterada. As outras sessões foram encerradas.');await load()}catch(e){setError(e instanceof Error?e.message:'Não foi possível alterar a senha.')}}
 async function exportData(){const p=window.prompt('Digite sua senha para autorizar a exportação dos dados:');if(!p)return;const c=mfa?.mfa_enabled?window.prompt('Digite o código MFA:')||'':'';try{const blob=await api.exportData({password:p,codigo_mfa:c});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='meu-controle-financeiro-dados.json';a.click();URL.revokeObjectURL(url);setMessage('Exportação criada com seus dados.')}catch(e){setError(e instanceof Error?e.message:'Não foi possível exportar os dados.')}}
 async function deleteAccount(){setError('');try{await api.deleteAccount({password,codigo_mfa:mfa?.mfa_enabled?mfaDisableCode:undefined,confirmacao:deleteText});onAccountDeleted()}catch(e){setError(e instanceof Error?e.message:'Não foi possível excluir a conta.')}}
 return <div className="security-panel"><div className="security-title"><div><span className="eyebrow">CENTRAL DE SEGURANÇA</span><h2>Proteja sua conta</h2><p>Camadas extras para manter seus dados financeiros sob seu controle.</p></div><Shield size={30}/></div>{message&&<div className="success-box">{message}</div>}{error&&<div className="form-error">{error}</div>}<div className="security-grid"><div className="soft-card"><div className="soft-card-icon"><Smartphone size={19}/></div><span>AUTENTICAÇÃO</span><h3>{mfa?.mfa_enabled?'MFA ativo':'MFA desativado'}</h3><small>{mfa?.mfa_enabled?'Além da senha, o login exige um código do seu aplicativo autenticador.':'Ative uma segunda camada para proteger a entrada na conta.'}</small>{!mfa?.mfa_enabled?<button className="text-btn setting-action" onClick={startMfa}>Ativar MFA <ChevronRight size={14}/></button>:<button className="text-btn setting-action" onClick={()=>{setShowPassword(false);setMfaDisableCode('')}}>MFA ativo</button>}</div><div className="soft-card"><div className="soft-card-icon"><KeyRound size={19}/></div><span>CREDENCIAL</span><h3>Senha da conta</h3><small>Troque a senha periodicamente. Com MFA ativo, o código também será exigido para a troca.</small><button className="text-btn setting-action" onClick={()=>setShowPassword(!showPassword)}>{showPassword?'Fechar':'Alterar senha'} <ChevronRight size={14}/></button></div><div className="soft-card"><div className="soft-card-icon"><Monitor size={19}/></div><span>SESSÕES</span><h3>{sessions.length} sessão(ões) ativa(s)</h3><small>Veja onde sua conta está aberta e encerre acessos que você não reconhece.</small><button className="text-btn setting-action" onClick={()=>api.revokeOtherSessions().then(load)}>Encerrar outras sessões</button><div className="session-list">{sessions.map(x=><div className="session-item" key={x.id}><div><strong>{x.atual?'Este dispositivo':'Outro dispositivo'}</strong><small>{x.user_agent?.slice(0,70)||'Navegador'} · {x.ip||'IP protegido'}</small></div>{!x.atual&&<button className="icon-btn small" onClick={()=>api.revokeSession(x.id).then(load)}><X size={14}/></button>}</div>)}</div></div><div className="soft-card"><div className="soft-card-icon"><Download size={19}/></div><span>SEUS DADOS</span><h3>Exportar meus dados</h3><small>Baixe uma cópia JSON dos dados financeiros associados à sua conta.</small><button className="text-btn setting-action" onClick={exportData}>Baixar meus dados <Download size={14}/></button></div></div><div className="soft-card audit-card"><div className="soft-card-icon"><Shield size={19}/></div><span>TRILHA DE SEGURANÇA</span><h3>Atividade recente</h3><div className="audit-list">{audit.slice(0,12).map((x,i)=><div className="audit-row" key={i}><div><strong>{x.evento.replaceAll('_',' ')}</strong><small>{new Date(x.criado_em).toLocaleString('pt-BR')}</small></div><span>{x.sucesso?'✓':'!'}</span></div>)}</div></div><div className="danger-zone"><div><span>ÁREA DE RISCO</span><h3>Excluir minha conta</h3><p>Remove permanentemente a conta e os dados vinculados. Essa ação não pode ser desfeita.</p></div><button className="danger-btn" onClick={()=>setShowDelete(true)}><Trash2 size={15}/> Excluir conta</button></div>{mfaSetup&&<Modal onClose={()=>setMfaSetup(null)}><span className="eyebrow">ATIVAR MFA</span><h3>Conecte seu aplicativo autenticador</h3><p className="modal-note">Adicione manualmente esta chave no Google Authenticator, Microsoft Authenticator, 1Password ou outro aplicativo compatível com TOTP.</p><div className="secret-box">{mfaSetup.secret}</div><p className="modal-note mono">{mfaSetup.otpauth_uri}</p><form onSubmit={e=>{e.preventDefault();void confirmMfa()}}><label>Código atual<input inputMode="numeric" maxLength={6} value={code} onChange={e=>setCode(e.target.value.replace(/\D/g,''))} required placeholder="000000"/></label><div className="confirm-actions"><button type="button" className="soft-btn" onClick={()=>setMfaSetup(null)}>Cancelar</button><button className="primary-btn">Confirmar MFA <Check size={16}/></button></div></form></Modal>}{showPassword&&<Modal onClose={()=>setShowPassword(false)}><span className="eyebrow">CREDENCIAL</span><h3>Alterar senha</h3><form onSubmit={e=>{e.preventDefault();void changePassword()}}><label>Senha atual<input type="password" value={password} onChange={e=>setPassword(e.target.value)} required/></label><label>Nova senha<input type="password" value={newPassword} onChange={e=>setNewPassword(e.target.value)} minLength={12} required placeholder="Mínimo de 12 caracteres"/></label>{mfa?.mfa_enabled&&<label>Código MFA<input inputMode="numeric" maxLength={6} value={mfaDisableCode} onChange={e=>setMfaDisableCode(e.target.value.replace(/\D/g,''))} required placeholder="000000"/></label>}<div className="confirm-actions"><button type="button" className="soft-btn" onClick={()=>setShowPassword(false)}>Cancelar</button><button className="primary-btn">Alterar senha <Check size={16}/></button></div></form></Modal>}{showDelete&&<Modal onClose={()=>setShowDelete(false)}><span className="eyebrow">ÚLTIMA ETAPA</span><h3>Excluir definitivamente?</h3><p className="modal-note">Esta ação apaga os dados da conta. Digite a frase abaixo para continuar.</p><div className="confirm-box"><strong>EXCLUIR MINHA CONTA</strong></div><form onSubmit={e=>{e.preventDefault();void deleteAccount()}}><label>Confirmação<input value={deleteText} onChange={e=>setDeleteText(e.target.value)} required placeholder="EXCLUIR MINHA CONTA"/></label><label>Senha atual<input type="password" value={password} onChange={e=>setPassword(e.target.value)} required/></label>{mfa?.mfa_enabled&&<label>Código MFA<input inputMode="numeric" maxLength={6} value={mfaDisableCode} onChange={e=>setMfaDisableCode(e.target.value.replace(/\D/g,''))} required placeholder="000000"/></label>}<div className="confirm-actions"><button type="button" className="soft-btn" onClick={()=>setShowDelete(false)}>Cancelar</button><button className="danger-btn">Excluir definitivamente <Trash2 size={15}/></button></div></form></Modal>}</div>
}

function ResetPassword(){const params=new URLSearchParams(window.location.search);const token=params.get('token')||'';const [password,setPassword]=useState(''),[confirm,setConfirm]=useState(''),[done,setDone]=useState(false),[error,setError]=useState(''),[loading,setLoading]=useState(false);async function submit(e:React.FormEvent){e.preventDefault();if(password!==confirm){setError('As senhas não conferem.');return}setLoading(true);try{await api.resetPassword({token,nova_senha:password});setDone(true)}catch(e){setError(e instanceof Error?e.message:'Link inválido ou expirado.')}finally{setLoading(false)}}return <div className="auth-screen"><div className="auth-art"><div className="brand"><Leaf size={18}/><strong>Meu Controle</strong></div><div className="auth-copy"><span className="eyebrow">RECUPERAÇÃO SEGURA</span><h1>Volte para sua conta<br/>com tranquilidade.</h1><p>O link de recuperação é temporário e pode ser usado uma única vez.</p></div><div className="auth-mascot">🔐<span>Sua conta merece cuidado.</span></div></div><div className="auth-card"><div className="mobile-brand"><Leaf size={18}/><strong>Meu Controle</strong></div>{done?<><span className="eyebrow">TUDO CERTO</span><h2>Senha redefinida</h2><p className="muted">As sessões anteriores foram encerradas. Você já pode entrar novamente.</p><button className="primary-btn wide" onClick={()=>window.location.href='/'}>Ir para o login <ChevronRight size={16}/></button></>:<><span className="eyebrow">NOVA SENHA</span><h2>Escolha uma nova senha</h2><p className="muted">Use pelo menos 12 caracteres.</p><form onSubmit={submit}><label>Nova senha<input type="password" minLength={12} value={password} onChange={e=>setPassword(e.target.value)} required/></label><label>Repetir senha<input type="password" minLength={12} value={confirm} onChange={e=>setConfirm(e.target.value)} required/></label>{error&&<div className="form-error">{error}</div>}<button className="primary-btn wide" disabled={loading}>{loading?'Salvando...':'Redefinir senha'}<Check size={16}/></button></form></>}</div></div>}


function AgendaPage(){
 const now=new Date(); const [month,setMonth]=useState(now.toISOString().slice(0,7)); const [data,setData]=useState<{eventos:any[]}|null>(null); const [notifs,setNotifs]=useState<any[]>([]); const [prefs,setPrefs]=useState<any>(null); const [loading,setLoading]=useState(true);
 const load=async()=>{setLoading(true);try{const [y,m]=month.split('-').map(Number);const start=`${month}-01`;const endDate=new Date(y,m,0);const end=`${month}-${String(endDate.getDate()).padStart(2,'0')}`;const [a,n,p]=await Promise.all([api.agenda(start,end),api.notifications(),api.notificationPreferences()]);setData(a);setNotifs(n.notificacoes);setPrefs(p)}finally{setLoading(false)}};useEffect(()=>{void load()},[month]);
 const grouped=useMemo(()=>{const map:Record<string,any[]>= {}; for(const e of data?.eventos||[])(map[e.data]??=[]).push(e);return map},[data]);
 async function browserNotify(){if(!('Notification' in window))return;const perm=await Notification.requestPermission();if(perm==='granted'&&notifs[0])new Notification('Meu Controle',{body:notifs[0].titulo});}
 return <section className="page-section"><PageHeader eyebrow="VISÃO DO TEMPO" title="Agenda financeira" text="Veja compromissos, vencimentos e metas no mesmo calendário." action={<div className="two" style={{alignItems:'center'}}><input type="month" value={month} onChange={e=>setMonth(e.target.value)}/><button className="soft-btn" onClick={browserNotify}><Bell size={16}/> Ativar avisos</button></div>}/><div className="content-grid"><section className="panel"><div className="panel-head"><div><span className="eyebrow">CALENDÁRIO</span><h3>{new Date(`${month}-01T12:00:00`).toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</h3></div></div>{loading?<div className="empty-state">Carregando agenda...</div>:Object.keys(grouped).length?Object.entries(grouped).map(([day,events])=><div className="list-row" key={day}><div className="row-icon neutral-bg"><CalendarDays size={16}/></div><div><strong>{dateBR(day)}</strong>{events.map((e:any)=><small key={e.id}>{e.titulo} · {e.tipo==='saida'?'Saída':e.tipo==='entrada'?'Entrada':e.tipo==='cartao'?'Cartão':'Meta'} {e.valor!=null?'· '+brl(e.valor):''}</small>)}</div></div>):<div className="empty-state">Nenhum compromisso neste mês. 🌿</div>}</section><section className="panel"><div className="panel-head"><div><span className="eyebrow">ALERTAS</span><h3>O que merece atenção</h3></div></div>{notifs.length?notifs.slice(0,8).map((n:any)=><div className="list-row" key={n.id}><div className={`row-icon ${n.prioridade==='alta'?'expense-bg':'neutral-bg'}`}><Bell size={16}/></div><div><strong>{n.titulo}</strong><small>{n.mensagem}</small></div></div>):<div className="empty-state">Nenhum alerta no momento. 🌱</div>}<div className="panel-head" style={{marginTop:18}}><div><span className="eyebrow">PREFERÊNCIAS</span><h3>Antecedência</h3></div></div>{prefs&&<label>Alertar com antecedência de {prefs.antecedencia_dias} dia(s)<input type="range" min="0" max="30" value={prefs.antecedencia_dias} onChange={async e=>{const v=Number(e.target.value);setPrefs({...prefs,antecedencia_dias:v});await api.saveNotificationPreferences({...prefs,antecedencia_dias:v})}}/></label>}<p className="modal-note">Os alertas apenas informam. Nenhum pagamento ou lançamento é criado automaticamente.</p></section></div></section>
}

function ReportsPage(){
 const [meses,setMeses]=useState(12); const [data,setData]=useState<any>(null); const [loading,setLoading]=useState(true);
 const load=()=>{setLoading(true);api.reports(meses).then(setData).finally(()=>setLoading(false))}; useEffect(()=>{load()},[meses]);
 const pct=(v:number,max:number)=>max?Math.max(4,Math.round(v/max*100)):4;
 const csv=()=>{if(!data)return; const rows=[['Mês','Entradas','Saídas','Resultado'],...data.tendencia.map((r:any)=>[r.mes,r.entradas,r.saidas,r.resultado])]; const cat=[['Categoria','Total','Quantidade'],...data.categorias.map((r:any)=>[r.categoria,r.total,r.quantidade])]; const all=[...rows,[''],...cat].map(r=>r.map((x:any)=>`"${String(x??'').replace(/"/g,'""')}"`).join(';')).join('\n'); const blob=new Blob([`\ufeff${all}`],{type:'text/csv;charset=utf-8'}); const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='meu-controle-relatorio.csv';a.click();URL.revokeObjectURL(a.href)};
 if(loading)return <section className="page-section"><PageHeader eyebrow="ANÁLISE" title="Relatórios" text="Organizando seus números..."/></section>;
 const max=Math.max(...(data.tendencia||[]).map((r:any)=>Math.max(r.entradas,r.saidas)),1); return <section className="page-section reports-page"><PageHeader eyebrow="VISÃO FINANCEIRA" title="Relatórios" text="Veja como seu dinheiro se comportou ao longo do tempo, sem complicação." action={<div className="report-actions"><select value={meses} onChange={e=>setMeses(Number(e.target.value))}><option value={6}>6 meses</option><option value={12}>12 meses</option><option value={24}>24 meses</option></select><button className="soft-btn" onClick={()=>window.print()}><Download size={16}/> Salvar PDF</button><button className="soft-btn" onClick={csv}><Download size={16}/> Exportar Excel</button></div>}/>
 <div className="metrics-grid"><div className="metric-card"><span>ENTRADAS NO MÊS</span><strong>{brl(data.atual.entradas)}</strong></div><div className="metric-card"><span>SAÍDAS NO MÊS</span><strong>{brl(data.atual.saidas)}</strong></div><div className="metric-card"><span>RESULTADO</span><strong>{brl(data.atual.resultado)}</strong></div><div className="metric-card"><span>LANÇAMENTOS PAGOS</span><strong>{data.atual.quantidade}</strong></div></div>
 <div className="content-grid"><section className="panel"><div className="panel-head"><div><span className="eyebrow">EVOLUÇÃO</span><h3>Entradas e saídas</h3></div></div><div className="report-bars">{data.tendencia.map((r:any)=><div className="report-bar-col" key={r.mes}><div className="report-bar-pair"><div className="report-bar income" style={{height:`${pct(r.entradas,max)}%`}} title={`Entradas ${brl(r.entradas)}`}></div><div className="report-bar expense" style={{height:`${pct(r.saidas,max)}%`}} title={`Saídas ${brl(r.saidas)}`}></div></div><small>{r.mes.slice(5)}</small></div>)}</div><div className="report-legend"><span><i className="legend-dot income"></i>Entradas</span><span><i className="legend-dot expense"></i>Saídas</span></div></section>
 <section className="panel"><div className="panel-head"><div><span className="eyebrow">DESPESAS</span><h3>Por categoria</h3></div></div>{data.categorias.slice(0,8).map((r:any)=><div className="report-category" key={r.categoria}><div><strong>{r.categoria}</strong><small>{r.quantidade} lançamento(s)</small></div><b>{brl(r.total)}</b><div className="report-progress"><span style={{width:`${pct(r.total,data.categorias[0]?.total||1)}%`}}></span></div></div>)}{!data.categorias.length&&<div className="empty-state">Ainda não há despesas suficientes para este relatório.</div>}</section></div>
 <div className="content-grid" style={{marginTop:18}}><section className="panel"><div className="panel-head"><div><span className="eyebrow">CONTAS</span><h3>Saldo por conta</h3></div></div>{data.contas.map((a:any)=><div className="list-row" key={a.id}><div className="row-icon neutral-bg"><Wallet size={16}/></div><div><strong>{a.nome}</strong><small>{a.tipo}</small></div><div className="row-right"><b>{brl(a.saldo_atual)}</b></div></div>)}</section><section className="panel"><div className="panel-head"><div><span className="eyebrow">CARTÕES</span><h3>Comprometimento</h3></div></div>{data.cartoes.map((c:any)=><div className="list-row" key={c.id}><div className="row-icon neutral-bg"><CreditCard size={16}/></div><div><strong>{c.nome}</strong><small>{c.disponivel==null?'Sem limite definido':`Disponível ${brl(c.disponivel)}`}</small></div><div className="row-right"><b>{brl(c.comprometido)}</b></div></div>)}{!data.cartoes.length&&<div className="empty-state">Nenhum cartão cadastrado.</div>}</section></div>
 <section className="panel" style={{marginTop:18}}><div className="panel-head"><div><span className="eyebrow">METAS</span><h3>Evolução dos objetivos</h3></div></div><div className="goal-report-grid">{data.metas.map((g:any)=>{const p=g.valor_objetivo?Math.min(100,g.valor_atual/g.valor_objetivo*100):0;return <div className="goal-report" key={g.id}><strong>{g.nome}</strong><span>{brl(g.valor_atual)} de {brl(g.valor_objetivo)}</span><div className="report-progress"><span style={{width:`${p}%`}}></span></div><small>{Math.round(p)}% concluído</small></div>})}{!data.metas.length&&<div className="empty-state">Nenhuma meta cadastrada.</div>}</div></section></section>}

function DocumentsPage(){
  const [payments,setPayments]=useState<Payment[]>([]); const [paymentId,setPaymentId]=useState(''); const [file,setFile]=useState<File|null>(null); const [result,setResult]=useState<any>(null); const [busy,setBusy]=useState(false); const load=()=>api.payments().then(setPayments).catch(()=>{}); useEffect(()=>{load()},[]);
  const submit=async()=>{if(!file||!paymentId)return;setBusy(true);try{const uploaded=await api.uploadDocument(file,paymentId);const analyzed=await api.analyzeDocument(uploaded.id);setResult(analyzed);setFile(null)}catch(e:any){alert(e.message||'Não foi possível analisar o documento')}finally{setBusy(false)}};
  return <section className="page-section"><PageHeader eyebrow="CAPTURA INTELIGENTE" title="Documentos" text="Envie um boleto, comprovante ou PDF para organizar informações antes de qualquer lançamento."/><div className="document-grid"><div className="panel"><div className="panel-head"><div><span className="eyebrow">1 · VINCULE</span><h3>Pagamento relacionado</h3></div></div><select className="input" value={paymentId} onChange={e=>setPaymentId(e.target.value)}><option value="">Selecione um pagamento</option>{payments.map(p=><option key={p.id} value={p.id}>{p.nome} · {p.data_prevista} · {p.valor_previsto==null?'valor variável':brl(p.valor_previsto)}</option>)}</select><div className="upload-box"><FileUp size={28}/><strong>PDF, JPG, PNG ou WEBP</strong><small>Até o limite configurado do aplicativo.</small><input type="file" accept="application/pdf,image/jpeg,image/png,image/webp" onChange={e=>setFile(e.target.files?.[0]||null)}/>{file&&<span>{file.name}</span>}</div><button className="primary-btn" disabled={!file||!paymentId||busy} onClick={submit}>{busy?'Analisando…':'Enviar e analisar'}</button></div><div className="panel"><div className="panel-head"><div><span className="eyebrow">2 · REVISÃO</span><h3>O que foi encontrado</h3></div></div>{!result?<div className="empty-state">Depois do envio, valores e datas encontrados aparecem aqui para você revisar.</div>:<div className="document-result"><div><strong>{result.nome_arquivo}</strong><small>Status: {result.status}</small></div><div><span>Valores encontrados</span><strong>{result.valores_encontrados?.length?result.valores_encontrados.map((v:number)=>brl(v)).join(' · '):'Nenhum valor identificado'}</strong></div><div><span>Datas encontradas</span><strong>{result.datas_encontradas?.length?result.datas_encontradas.join(' · '):'Nenhuma data identificada'}</strong></div><p>{result.observacao}</p></div>}</div></div></section>
}

function SettingsPage({user,mascot,onMascot,onAccountDeleted}:{user:User;mascot:Mascot;onMascot:(m:Mascot)=>void;onAccountDeleted:()=>void}){const [show,setShow]=useState(false);return <section className="page-section"><PageHeader eyebrow="SEU ESPAÇO" title="Configurações" text="Ajuste o Meu Controle para ficar cada vez mais com a sua cara."/><div className="settings-grid"><div className="soft-card"><div className="soft-card-icon"><UserRound size={19}/></div><span>PERFIL</span><h3>{user.nome}</h3><small>{user.email}</small></div><div className="soft-card"><div className="soft-card-icon">{mascot.emoji}</div><span>SEU MASCOTE</span><h3>{mascot.name}</h3><small>{mascot.personality}</small><button className="text-btn setting-action" onClick={()=>setShow(true)}>Trocar mascote <ChevronRight size={14}/></button></div><div className="soft-card"><div className="soft-card-icon"><Shield size={19}/></div><span>SEGURANÇA</span><h3>Defesa em camadas</h3><small>Cookie HttpOnly, CSRF, rate limiting, sessões revogáveis, MFA e trilha de segurança.</small></div><div className="soft-card"><div className="soft-card-icon"><BarChart3 size={19}/></div><span>MEMÓRIA FINANCEIRA</span><h3>Padrões sem julgamento</h3><small>O sistema pode sugerir repetições, mas nunca cria compromissos sozinho.</small></div></div><PrivacyPanel/><SecurityPanel onAccountDeleted={onAccountDeleted}/>{show&&<MascotPicker initial={mascot.id} onSelect={async m=>{const u=await api.setMascot(m.id);onMascot(m);void u;setShow(false)}}/>}</section>}

function Modal({children,onClose}:{children:React.ReactNode;onClose:()=>void}){return <div className="modal-backdrop"><div className="modal"><button className="close-pop modal-close" onClick={onClose}><X size={16}/></button>{children}</div></div>}


function IntelligencePage({mascot}:{mascot:Mascot}){
 const [data,setData]=useState<any>(null); const [loading,setLoading]=useState(true);
 useEffect(()=>{api.intelligence().then(setData).catch(()=>{}).finally(()=>setLoading(false))},[]);
 if(loading)return <section className="page-section"><PageHeader eyebrow="INTELIGÊNCIA" title="Minha Vida Financeira" text="Juntando as peças do seu dinheiro em uma visão simples."/><div className="empty-state">Organizando seus dados... 🌿</div></section>;
 if(!data)return <section className="page-section"><PageHeader eyebrow="INTELIGÊNCIA" title="Minha Vida Financeira" text="Não foi possível carregar a visão agora."/></section>;
 return <section className="page-section">
  <PageHeader eyebrow="INTELIGÊNCIA FINANCEIRA" title="Minha Vida Financeira" text="Uma leitura dos seus dados para ajudar você a enxergar padrões, capacidade e próximos passos."/>
  <div className="metric-grid"><div className="metric-card"><span>Patrimônio financeiro</span><strong>{brl(data.patrimonio.total)}</strong><small>Contas + investimentos</small></div><div className="metric-card"><span>Entradas médias</span><strong>{brl(data.medias.entradas)}</strong><small>Últimos meses registrados</small></div><div className="metric-card"><span>Saídas médias</span><strong>{brl(data.medias.saidas)}</strong><small>Últimos meses registrados</small></div><div className="metric-card"><span>Capacidade média</span><strong>{brl(data.medias.capacidade)}</strong><small>Entradas menos saídas</small></div></div>
  <div className="content-grid" style={{marginTop:18}}><section className="panel"><div className="panel-head"><div><span className="eyebrow">LEITURA</span><h3>O que os seus dados mostram</h3></div></div>{data.notas.map((n:string,i:number)=><div className="list-row" key={i}><div className="row-icon neutral-bg"><Sparkles size={16}/></div><div><strong>Insight {i+1}</strong><small>{n}</small></div></div>)}</section>
  <section className="panel"><div className="panel-head"><div><span className="eyebrow">PATRIMÔNIO</span><h3>Composição atual</h3></div></div><div className="list-row"><div><strong>Contas</strong><small>Saldo financeiro disponível</small></div><b>{brl(data.patrimonio.contas)}</b></div><div className="list-row"><div><strong>Investimentos</strong><small>Valor atual registrado</small></div><b>{brl(data.patrimonio.investimentos)}</b></div><div className="list-row"><div><strong>Resultado dos investimentos</strong><small>Diferença entre atual e investido</small></div><b>{brl(data.patrimonio.ganho_investimentos)}</b></div></section></div>
  <section className="panel" style={{marginTop:18}}><div className="panel-head"><div><span className="eyebrow">CENÁRIOS</span><h3>Se sua capacidade média se mantiver</h3></div></div><div className="scenario-cards">{data.cenarios.map((c:any)=><div className="scenario-card" key={c.nome}><span>{c.nome}</span><strong>{brl(c.aporte)}/mês</strong><small>Patrimônio estimado em 12 meses: {brl(c.patrimonio_12_meses)}</small></div>)}</div><p className="modal-note">São simulações, não previsões. Não consideram rentabilidade de investimentos nem movimentam dinheiro.</p></section>
  <div className="content-grid" style={{marginTop:18}}><section className="panel"><div className="panel-head"><div><span className="eyebrow">METAS</span><h3>Distância até seus objetivos</h3></div></div>{data.metas.length?data.metas.map((g:any)=><div className="planning-goal" key={g.id}><div className="planning-goal-head"><div><strong>{g.nome}</strong><small>{brl(g.restante)} restantes</small></div><b>{g.aporte_necessario!==null?brl(g.aporte_necessario)+'/mês':'Sem prazo'}</b></div></div>):<div className="empty-state">Nenhuma meta ativa.</div>}</section><section className="panel"><div className="panel-head"><div><span className="eyebrow">PADRÕES</span><h3>Comportamentos recorrentes</h3></div></div>{data.padroes.length?data.padroes.slice(0,5).map((p:any)=><div className="list-row" key={p.descricao_normalizada}><div><strong>{p.descricao_normalizada}</strong><small>{p.ocorrencias} ocorrência(s) · média {brl(p.media_valor)}</small></div>{p.recorrencia_detectada&&<span className="status-pill">Recorrente</span>}</div>):<div className="empty-state">Ainda não há padrões suficientes.</div>}</section></div>
  <div className="panel mascot-insight" style={{marginTop:18}}><span className="mascot-emoji">{mascot.emoji}</span><div><span className="eyebrow">SEU COMPANHEIRO</span><h3>Sem pressão: informação primeiro.</h3><p>Use esta visão para entender o momento financeiro. Qualquer ação que movimente dinheiro continua dependendo da sua confirmação.</p></div></div>
 </section>
}


function AssistantPage(){
 const [question,setQuestion]=useState(''); const [loading,setLoading]=useState(false); const [history,setHistory]=useState<any[]>([]); const [smart,setSmart]=useState<any|null>(null);
 useEffect(()=>{Promise.all([api.assistantInsights(),api.assistantHistory()]).then(([ins,h])=>{setSmart(ins);setHistory((h.historico||[]).reverse())}).catch(()=>{})},[]);
 const ask=async(q?:string)=>{const text=(q??question).trim();if(!text)return;setLoading(true);try{const r=await api.assistantAsk(text);setHistory(h=>[...h,{...r}]);setQuestion('')}catch(e:any){alert(e.message||'Não foi possível consultar o assistente')}finally{setLoading(false)}};
 const suggestions=['Quanto gastei com alimentação nos últimos 3 meses?','Quanto tenho hoje em patrimônio?','Como está minha meta?','Quais compromissos tenho nos próximos 30 dias?'];
 return <section className="page-section"><PageHeader eyebrow="ASSISTENTE FINANCEIRO" title="Converse com seus dados" text="Pergunte sobre seus registros. O assistente consulta, calcula, explica e sugere — não movimenta dinheiro."/>
 {smart&&<div className="content-grid" style={{marginBottom:18}}><section className="panel"><div className="panel-head"><div><span className="eyebrow">LEITURA INTELIGENTE</span><h3>O que mudou e merece atenção</h3></div></div>{smart.insights?.length?smart.insights.map((x:any,i:number)=><div className="list-row" key={i}><div className="row-icon neutral-bg">✦</div><div><strong>{x.titulo}</strong><small>{x.texto}</small></div></div>):<div className="empty-state">Ainda não há mudanças relevantes suficientes para explicar.</div>}</section><section className="panel"><div className="panel-head"><div><span className="eyebrow">SUGESTÕES</span><h3>Próximos acompanhamentos</h3></div></div>{smart.recommendations?.length?smart.recommendations.map((x:any,i:number)=><div className="list-row" key={i}><div className="row-icon neutral-bg">✓</div><div><strong>{x.titulo}</strong><small>{x.texto}</small></div></div>):<div className="empty-state">Nenhuma sugestão contextual no momento.</div>}</section></div>}
 <div className="panel assistant-history-note" style={{marginBottom:18}}><div className="panel-head"><div><span className="eyebrow">HISTÓRICO</span><h3>Suas consultas ficam organizadas</h3></div></div><p className="modal-note">As perguntas e respostas ficam vinculadas à sua conta para você continuar de onde parou. Esse histórico não autoriza nenhuma movimentação financeira.</p></div><div className="assistant-panel"><div className="assistant-suggestions">{suggestions.map(x=><button key={x} onClick={()=>ask(x)}>{x}</button>)}</div><div className="assistant-history">{history.length===0?<div className="empty-state">Experimente uma das perguntas acima. Se um dado não estiver registrado, eu aviso em vez de inventar.</div>:history.map((x,i)=><div className="assistant-answer" key={i}><small>Você perguntou</small><strong>{x.pergunta}</strong><p>{x.resposta}</p><span>Informativo · baseado somente nos registros disponíveis · nenhuma movimentação foi realizada.</span></div>)}</div><div className="assistant-input"><input value={question} onChange={e=>setQuestion(e.target.value)} onKeyDown={e=>{if(e.key==='Enter')void ask()}} placeholder="Ex.: quanto gastei com alimentação?"/><button className="primary-btn" disabled={!question.trim()||loading} onClick={()=>void ask()}>{loading?'Consultando…':'Perguntar'}</button></div></div></section>
}

function App(){const [user,setUser]=useState<User|null>(null),[mascot,setMascot]=useState<Mascot|null>(null),[page,setPage]=useState<Page>('inicio'),[boot,setBoot]=useState(true);useEffect(()=>{api.me().then(u=>{setUser(u);setMascot(u.mascote_id?mascotById(u.mascote_id):null)}).catch(()=>{}).finally(()=>setBoot(false))},[]);if(window.location.pathname==='/redefinir-senha')return <ResetPassword/>;if(boot)return <div className="loading-screen">🌿</div>;if(!user)return <Auth onAuth={u=>{setUser(u);setMascot(u.mascote_id?mascotById(u.mascote_id):null)}}/>;if(!mascot)return <MascotPicker initial={user.mascote_id} onSelect={async m=>{const u=await api.setMascot(m.id);setUser(u);setMascot(m)}}/>;const content=page==='inicio'?<Home user={user} mascot={mascot} onNavigate={setPage}/>:page==='lancamentos'?<TransactionsPage/>:page==='contas'?<AccountsPage/>:page==='recorrencias'?<RecurrencesPage/>:page==='cartoes'?<CardsPage/>:page==='dividas'?<DebtsPage/>:page==='documentos'?<DocumentsPage/>:page==='investimentos'?<InvestmentsPage/>:page==='metas'?<GoalsPage/>:page==='agenda'?<AgendaPage/>:page==='relatorios'?<ReportsPage/>:page==='inteligencia'?<IntelligencePage mascot={mascot}/>:page==='assistente'?<AssistantPage/>:<SettingsPage user={user} mascot={mascot} onMascot={setMascot} onAccountDeleted={()=>{setUser(null);setMascot(null)}}/>;return <Shell page={page} setPage={setPage} user={user} mascot={mascot} onLogout={async()=>{try{await api.logout()}catch{}setUser(null);setMascot(null)}}>{content}</Shell>}

createRoot(document.getElementById('root')!).render(<React.StrictMode><App/></React.StrictMode>);
